/// Information about a type
/// for each variant
///     - module is the module where the type is defined (None for current module)
///     - rs_typ is the rust traduction of the type
#[allow(clippy::large_enum_variant)]
#[derive(Clone, Debug)]
enum TypeInfo {
    /// simple copyable types such as u32
    Simple {
        rs_typ: String,
        wire_sz: usize,
        has_wire_layout: bool,
    },
    Typedef {
        module: Option<String>,
        rs_typ: String,
        old_module: Option<String>,
        old_typ: String,
        wire_sz: Expr,
        has_wire_layout: bool,
    },
    Xid {
        module: Option<String>,
        rs_typ: String,
    },
    XidUnion {
        module: Option<String>,
        rs_typ: String,
        variants: Vec<UnionVariant>,
    },
    Enum {
        module: Option<String>,
        rs_typ: String,
        items: Vec<(String, u32, Option<String>)>,
        doc: Option<Doc>,
    },
    Mask {
        module: Option<String>,
        rs_typ: String,
        items: Vec<(String, u32, Option<String>)>,
        doc: Option<Doc>,
    },
    Struct {
        module: Option<String>,
        rs_typ: String,
        fields: Vec<Field>,
        wire_sz: Expr,
        has_wire_layout: bool,
        params_struct: Option<ParamsStruct>,
        doc: Option<Doc>,
    },
    Union {
        module: Option<String>,
        rs_typ: String,
        variants: Vec<UnionVariant>,
        wire_sz: Expr,
        type_field: Option<UnionTypeField>,
    },
    Switch {
        module: Option<String>,
        rs_typ: String,
        expr: Expr,
        cases: Vec<SwitchCase>,
        maskenum: (Option<String>, String),
        params_struct: ParamsStruct,
        wire_sz: Expr,
        is_mask: bool,
        emit: bool,
    },
}

#[derive(Clone, Debug)]
struct SwitchCase {
    name: String,
    exprs: Vec<Expr>,
    fields: Vec<Field>,
}

#[derive(Clone, Debug)]
enum Field {
