impl CodeGen {
    pub(super) fn resolve_request(
        &mut self,
        name: String,
        opcode: u32,
        mut params: Vec<ir::Field>,
        reply: Option<ir::Reply>,
        doc: Option<ir::Doc>,
    ) {
        if self.xcb_mod == "xinput" && name == "SendExtensionEvent" {
            // FIXME: xinput request that depend on event
            return;
        }
        // special case for the request that send events
        let sends_event = matches!(
            (self.xcb_mod.as_str(), name.as_str()),
            ("xproto", "SendEvent") | ("xevie", "Send")
        );

        // let event_is_list = sends_event
        //     && params
        //         .iter()
        //         .any(|p| matches!(p, ir::Field::List{name, ..} if name == "Event"));

        let rs_typ = cg::rust_type_name(&name);
        let doc = self.resolve_doc(doc);

        let params = {
            let mut fields = vec![
                make_field("major_opcode".into(), "CARD8".into()),
                if self.xcb_mod == "xproto" {
                    if params.is_empty() {
                        ir::Field::Pad(1)
                    } else {
                        params.remove(0)
                    }
                } else {
                    make_field("minor_opcode".into(), "CARD8".into())
                },
                make_field("length".into(), "CARD16".into()),
            ];
            fields.append(&mut params);
            fields
        };

        let ResolvedFields {
            fields: mut params, ..
        } = self.resolv_struct_fields(&rs_typ, "", &params, doc.as_ref());

        let req_rs_typ = &rs_typ;

        for param in &mut params {
            if let Field::Field {
                name,
                ref mut rs_typ,
                ..
            } = param
            {
                if self.xcb_mod == "xproto"
                    && req_rs_typ == "SendEvent"
                    && name == "destination"
                    && rs_typ == "Window"
                {
                    *rs_typ = "SendEventDest".to_string();
                }
            }
        }

        let reply = reply.map(|mut r| {
            let rs_typ = rs_typ.clone() + "Reply";
            let doc = self.resolve_doc(r.doc);
            let mut fields = vec![
                make_field("response_type".into(), "CARD8".into()),
                if r.fields.is_empty() {
                    ir::Field::Pad(1usize)
                } else {
                    r.fields.remove(0)
                },
                make_field("sequence".into(), "CARD16".into()),
                make_field("length".into(), "CARD32".into()),
            ];
            fields.append(&mut r.fields);
            let ResolvedFields { fields, .. } =
                self.resolv_struct_fields(&rs_typ, "", &fields, doc.as_ref());

            Reply { fields, doc }
        });
        self.requests.push(Request {
            rs_typ,
            opcode,
            params,
            reply,
            sends_event,
            doc,
            // event_is_list,
        });
    }

    pub fn emit_requests<O: Write>(&self, out: &mut O) -> io::Result<()> {
        for r in &self.requests {
            let Request {
                rs_typ,
                opcode,
                params,
                reply,
                sends_event,
                doc,
            } = r;

            let info = self.query_request_info(rs_typ, params, *opcode, reply.is_none());

            if let Some(reply) = reply {
                self.emit_cookie_reply(out, reply, &info)?;
            }

            self.emit_request_struct(out, rs_typ, params, &info, doc.as_ref(), *sends_event)?;

            self.emit_request_traits(out, rs_typ, params, &info, *sends_event)?;
        }
        Ok(())
    }

    fn query_request_info<'a>(
        &self,
        rs_typ: &str,
        params: &'a [Field],
        opcode: u32,
        is_void: bool,
    ) -> RequestInfo<'a> {
        let mut last_fixed = true;
        let mut has_lt = false;
        let mut sections = Vec::new();
        let mut start = 0;
        let mut end = 0;

        let mut field = |is_fixed: bool| {
            end += 1;
            if is_fixed && !last_fixed {
                assert_eq!(end, start + 1);
                sections.push(SerializeSection::Var(&params[start]));
                start = end;
            } else if !is_fixed {
                sections.push(SerializeSection::Fixed(&params[start..end - 1]));
                start = end;
            }
            last_fixed = is_fixed;
        };

        for p in params {
            match p {
                Field::Field {
                    struct_style: Some(StructStyle::DynBuf),
                    ..
                } => {
                    field(false);
                    has_lt = true;
                }
                Field::Field { .. } => {
                    field(true);
                }
                Field::List {
                    struct_style: Some(StructStyle::DynBuf),
                    len_expr: Expr::Value(_),
                    ..
                } => {
                    field(false);
                    has_lt = true;
                }
                Field::List {
                    len_expr: Expr::Value(_),
                    ..
                } => {
                    field(true);
                }
                Field::List { .. } => {
                    field(false);
                    has_lt = true;
                }
                Field::Switch { is_mask, .. } => {
                    field(false);
                    if *is_mask {
                        has_lt = true;
                    }
                }
                Field::Expr { .. } => {
                    field(true);
                }
                Field::Pad { .. } => {
                    field(true);
                }
                Field::AlignPad { .. } => {
                    //assert!(last_fixed);
                    field(false);
                }
            }
        }

        if last_fixed {
            sections.push(SerializeSection::Fixed(&params[start..end]));
        } else {
            sections.push(SerializeSection::Var(&params[start - 1]));
        }

        let (cookie_rs_typ, reply_rs_typ) = if is_void {
            ("base::VoidCookie".to_string(), "()".to_string())
        } else {
            (rs_typ.to_string() + "Cookie", rs_typ.to_string() + "Reply")
        };

        let has_prop_field = params.iter().any(|p| {
            matches!(
                p,
                Field::Field {
                    is_prop_format: true,
                    ..
                }
            )
        });

        RequestInfo {
            rs_typ: rs_typ.to_string(),
            cookie_rs_typ,
            reply_rs_typ,
            sections,
            has_lifetime: has_lt,
            opcode,
            is_void,
            has_prop_field,
        }
    }

    fn emit_cookie_reply<O: Write>(
        &self,
        out: &mut O,
        reply: &Reply,
        info: &RequestInfo,
    ) -> io::Result<()> {
        let RequestInfo {
            rs_typ: req_name,
            cookie_rs_typ,
            reply_rs_typ,
            ..
        } = info;

        writeln!(out)?;
        if let Some(doc) = &reply.doc {
            doc.emit(out, 0)?;
        }
        writeln!(out, "pub struct {} {{", reply_rs_typ)?;
        writeln!(out, "    raw: *const u8,")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "impl {} {{", reply_rs_typ)?;
        writeln!(out)?;
        writeln!(out, "    fn wire_ptr(&self) -> *const u8 {{")?;
        writeln!(out, "        self.raw")?;
        writeln!(out, "    }}")?;

        for f in &reply.fields {
            if let Field::Field {
                struct_style: Some(StructStyle::DynBuf),
                ..
            }
            | Field::List { .. } = f
            {
                let len_stmts =
                    self.emit_compute_offset_and_get_stmts(out, reply_rs_typ, &reply.fields, None)?;
                self.emit_compute_func(out, "compute_len", None, &len_stmts)?;
                break;
            }
        }
        self.emit_struct_accessors(out, reply_rs_typ, &reply.fields)?;

        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "impl base::Reply for {} {{", reply_rs_typ)?;
        writeln!(out, "    unsafe fn from_raw(raw: *const u8) -> Self {{")?;
        writeln!(out, "        Self {{ raw }}")?;
        writeln!(out, "    }}")?;
        writeln!(out)?;
        writeln!(out, "    unsafe fn into_raw(self) -> *const u8 {{")?;
        writeln!(out, "        let raw = self.raw;")?;
        writeln!(out, "        std::mem::forget(self);")?;
        writeln!(out, "        raw")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        self.emit_debug_impl(out, reply_rs_typ, &reply.fields)?;

        writeln!(out)?;
        writeln!(out, "impl Drop for {} {{", reply_rs_typ)?;
        writeln!(out, "    fn drop(&mut self) {{")?;
        writeln!(out, "        unsafe {{ libc::free(self.raw as *mut _); }}")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "/// Cookie type for [{}]", req_name)?;
        writeln!(out, "///")?;
        writeln!(out, "/// This cookie can be used to get a {}", reply_rs_typ)?;
        writeln!(out, "/// result with `Connection::wait_for_reply`")?;
        writeln!(out, "#[derive(Debug)]")?;
        writeln!(out, "pub struct {} {{", cookie_rs_typ)?;
        writeln!(out, "    seq: u64,")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "#[derive(Debug)]")?;
        writeln!(out, "/// Unchecked cookie type for [{}]", req_name)?;
        writeln!(out, "///")?;
        writeln!(out, "/// This cookie can be used to get a {}", reply_rs_typ)?;
        writeln!(
            out,
            "/// result with `Connection::wait_for_reply_unchecked`"
        )?;
        writeln!(out, "pub struct Unchecked{} {{", cookie_rs_typ)?;
        writeln!(out, "    seq: u64,")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "impl base::Cookie for {} {{", cookie_rs_typ)?;
        writeln!(out, "    unsafe fn from_sequence(seq: u64) -> Self {{")?;
        writeln!(out, "        {} {{ seq }}", cookie_rs_typ)?;
        writeln!(out, "    }}")?;
        writeln!(out)?;
        writeln!(out, "    fn sequence(&self) -> u64 {{")?;
        writeln!(out, "        self.seq")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(
            out,
            "unsafe impl base::CheckedCookie for {} {{",
            cookie_rs_typ
        )?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(
            out,
            "unsafe impl base::CheckedCookieWithReply for {} {{",
            cookie_rs_typ
        )?;
        writeln!(out, "    type Reply = {};", reply_rs_typ)?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "impl base::Cookie for Unchecked{} {{", cookie_rs_typ)?;
        writeln!(out, "    unsafe fn from_sequence(seq: u64) -> Self {{")?;
        writeln!(out, "        Unchecked{} {{ seq }}", cookie_rs_typ)?;
        writeln!(out, "    }}")?;
        writeln!(out)?;
        writeln!(out, "    fn sequence(&self) -> u64 {{")?;
        writeln!(out, "        self.seq")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(
            out,
            "unsafe impl base::UncheckedCookieWithReply for Unchecked{} {{",
            cookie_rs_typ
        )?;
        writeln!(out, "    type Reply = {};", reply_rs_typ)?;
        writeln!(out, "}}")?;

        Ok(())
    }

    fn emit_request_struct<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        params: &[Field],
        info: &RequestInfo,
        doc: Option<&Doc>,
        sends_event: bool,
    ) -> io::Result<()> {
        let (generic_decl, _) = self.generic_decl_and_use(sends_event, info);

        writeln!(out)?;
        if let Some(doc) = doc {
            doc.emit(out, 0)?;
        }
        writeln!(out, "#[derive(Clone, Debug)]")?;
        writeln!(out, "pub struct {}{} {{", rs_typ, generic_decl)?;
        for p in params {
            match p {
                Field::Field { name, doc, .. } | Field::List { name, doc, .. }
                    if sends_event && name == "event" =>
                {
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "{}pub event: &'a E,", cg::ind(1))?;
                }
                Field::Field {
                    name,
                    module,
                    rs_typ,
                    is_fieldref,
                    struct_style: Some(StructStyle::DynBuf),
                    doc,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    if !is_fieldref {
                        if let Some(doc) = doc {
                            doc.emit(out, 1)?;
                        }
                        writeln!(out, "    pub {}: &'a {},", name, q_rs_typ)?;
                    }
                }
                Field::Field {
                    name,
                    module,
                    rs_typ,
                    is_fieldref,
                    r#enum,
                    mask,
                    is_prop_format,
                    doc,
                    ..
                } => {
                    if name == "major_opcode" || name == "minor_opcode" || name == "length" {
                        // These fields are written on the wire, but not needed as parameters.
                        // They are filled in by XCB directly
                        continue;
                    }
                    if *is_prop_format {
                        // format field is inferred from the property data field
                        continue;
                    }

                    let q_rs_typ =
                        r#struct::enum_mask_qualified_rs_typ(module, rs_typ, r#enum, mask);
                    if !is_fieldref || request_fieldref_emitted(name, params, info.has_prop_field) {
                        if let Some(doc) = doc {
                            doc.emit(out, 1)?;
                        }
                        writeln!(out, "    pub {}: {},", name, q_rs_typ)?;
                    }
                }
                Field::List {
                    name,
                    module,
                    rs_typ,
                    struct_style: Some(StructStyle::DynBuf),
                    len_expr: Expr::Value(len),
                    doc,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "    pub {}: [{}Buf; {}],", name, q_rs_typ, len)?;
                }
                Field::List {
                    name,
                    module,
                    rs_typ,
                    len_expr: Expr::Value(len),
                    doc,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "    pub {}: [{}; {}],", name, q_rs_typ, len)?;
                }
                Field::List {
                    name,
                    module,
                    rs_typ,
                    struct_style: Some(StructStyle::DynBuf),
                    doc,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "    pub {}: &'a [{}Buf],", name, q_rs_typ)?;
                }
                Field::List {
                    name, rs_typ, doc, ..
                } if rs_typ == "char" => {
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "    pub {}: &'a str,", name)?;
                }
                Field::List {
                    name,
                    module,
                    rs_typ,
                    is_prop,
                    doc,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    let typ = if *is_prop { "P" } else { &q_rs_typ };
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "    pub {}: &'a [{}],", name, typ)?;
                }
                Field::Switch {
                    name,
                    module,
                    rs_typ,
                    is_mask,
                    doc,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    if *is_mask {
                        writeln!(out, "    pub {}: &'a [{}],", name, q_rs_typ)?;
                    } else {
                        writeln!(out, "    pub {}: {},", name, q_rs_typ)?;
                    }
                }
                _ => {}
            }
        }
        writeln!(out, "}}")?;
        Ok(())
    }

    fn emit_request_traits<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        params: &[Field],
        info: &RequestInfo,
        sends_event: bool,
    ) -> io::Result<()> {
        self.emit_raw_request(out, rs_typ, params, info, sends_event)?;

        let (generic_decl, generic_use) = self.generic_decl_and_use(sends_event, info);

        let RequestInfo {
            is_void,
            cookie_rs_typ,
            reply_rs_typ,
            ..
        } = info;

        writeln!(out)?;
        writeln!(
            out,
            "impl{} base::Request for {}{} {{",
            generic_decl, rs_typ, generic_use
        )?;
        writeln!(out, "    type Cookie = {};", cookie_rs_typ)?;
        writeln!(out, "    const IS_VOID: bool = {};", is_void)?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(
            out,
            "impl{} base::Request{}Reply for {}{} {{",
            generic_decl,
            if *is_void { "Without" } else { "With" },
            rs_typ,
            generic_use
        )?;

        if !*is_void {
            writeln!(out, "    type Reply = {};", reply_rs_typ)?;
            writeln!(out, "    type Cookie = {};", cookie_rs_typ)?;
            writeln!(
                out,
                "    type UncheckedCookie = Unchecked{};",
                cookie_rs_typ
            )?;
        }

        writeln!(out, "}}")?;

        Ok(())
    }

    fn generic_decl_and_use(&self, sends_event: bool, info: &RequestInfo) -> (&str, &str) {
        if sends_event {
            ("<'a, E: base::BaseEvent>", "<'a, E>")
        } else if info.has_prop_field {
            ("<'a, P: PropEl>", "<'a, P>")
        } else if info.has_lifetime {
            ("<'a>", "<'a>")
        } else {
            ("", "")
        }
    }

    fn emit_raw_request<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        params: &[Field],
        info: &RequestInfo,
        sends_event: bool,
    ) -> io::Result<()> {
        let (generic_decl, generic_use) = self.generic_decl_and_use(sends_event, info);

        let RequestInfo {
            sections,
            opcode,
            is_void,
            ..
        } = info;

        let parts_count = 2 * sections.len();
        // the C implementation always start with two iovec untouched (not sure why)
        let iovec_count = parts_count + 2;

        writeln!(out)?;
        writeln!(
            out,
            "unsafe impl{} base::RawRequest for {}{} {{",
            generic_decl, rs_typ, generic_use
        )?;
        writeln!(
            out,
            "    fn raw_request(&self, c: &base::Connection, checked: bool) -> u64 {{ unsafe {{",
        )?;
        self.emit_req_assertions(out, rs_typ, params)?;
        writeln!(
            out,
            "{}let mut protocol_request = xcb_protocol_request_t {{",
            cg::ind(2),
        )?;
        writeln!(out, "{}count: {},", cg::ind(3), parts_count)?;
        if self.xcb_mod == "xproto" {
            writeln!(out, "{}ext: std::ptr::null_mut(),", cg::ind(3))?;
        } else {
            writeln!(out, "{}ext: (&mut FFI_EXT) as *mut _,", cg::ind(3))?;
        }
        writeln!(out, "{}opcode: {},", cg::ind(3), opcode)?;
        writeln!(
            out,
            "{}isvoid: {},",
            cg::ind(3),
            if *is_void { 1 } else { 0 }
        )?;
        writeln!(out, "{}}};", cg::ind(2))?;
        writeln!(out)?;
        writeln!(
            out,
            "{}let mut sections: [iovec; {}] = [iovec {{",
            cg::ind(2),
            iovec_count
        )?;
        writeln!(out, "{}    iov_base: std::ptr::null_mut(),", cg::ind(2))?;
        writeln!(out, "{}    iov_len: 0,", cg::ind(2))?;
        writeln!(out, "{}}}; {}];", cg::ind(2), iovec_count)?;

        for (num, sect) in info.sections.iter().enumerate() {
            writeln!(out)?;
            match sect {
                SerializeSection::Fixed(fields) => {
                    self.emit_req_fixed_buf(out, num, fields, params, info, sends_event)?;
                }
                SerializeSection::Var(field) => {
                    self.emit_req_var_buf(out, num, field)?;
                }
            }
            writeln!(
                out,
                "{}sections[{}].iov_len = base::align_pad(sections[{}].iov_len, 4);",
                cg::ind(2),
                num * 2 + 3,
                num * 2 + 2
            )?;
        }

        writeln!(out)?;
        writeln!(
            out,
            "{}let flags = if checked {{ 1 }} else {{ 0 }};",
            cg::ind(2)
        )?;
        writeln!(out)?;
        writeln!(out, "{}xcb_send_request64(", cg::ind(2))?;
        writeln!(out, "{}    c.get_raw_conn(),", cg::ind(2))?;
        writeln!(out, "{}    flags,", cg::ind(2))?;
        writeln!(out, "{}    sections.as_mut_ptr().add(2),", cg::ind(2))?;
        writeln!(out, "{}    &mut protocol_request as *mut _", cg::ind(2))?;
        writeln!(out, "{})", cg::ind(2))?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}}}")?;

        Ok(())
    }

    fn emit_req_assertions<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        params: &[Field],
    ) -> io::Result<()> {
        for p in params {
            if let Field::Switch {
                name,
                module,
                rs_typ: f_rs_typ,
                is_mask: true,
                ..
            } = p
            {
                let q_rs_typ = (module, f_rs_typ).qualified_rs_typ();
                writeln!(
                    out,
                    "{}assert!({}::is_sorted_distinct(self.{}), \"{}::{} must be sorted!\");",
                    cg::ind(2),
                    q_rs_typ,
                    name,
                    rs_typ,
                    name
                )?;
            }
        }
        Ok(())
    }

    fn emit_req_fixed_buf<O: Write>(
        &self,
        out: &mut O,
        num: usize,
        fields: &[Field],
        params: &[Field],
        info: &RequestInfo,
        sends_event: bool,
    ) -> io::Result<()> {
        let sz = self.fixed_fields_size(fields);
        writeln!(
            out,
            "{}let buf{}: &mut [u8] = &mut [0; {}];",
            cg::ind(2),
            num,
            sz,
        )?;
        let mut offset = 0;
        for f in fields {
            match f {
                Field::Field { name, .. } | Field::List { name, .. }
                    if sends_event && name == "event" =>
                {
                    writeln!(out, "{}std::slice::from_raw_parts_mut(", cg::ind(2))?;
                    writeln!(
                        out,
                        "{}    buf{}.as_mut_ptr().add({}), 32",
                        cg::ind(2),
                        num,
                        offset,
                    )?;
                    writeln!(
                        out,
                        "{}).copy_from_slice(self.{}.as_slice());",
                        cg::ind(2),
                        name
                    )?;
                    offset += 32;
                }
                Field::Field {
                    name,
                    wire_sz: Expr::Value(sz),
                    ..
                } if name == "major_opcode" || name == "minor_opcode" || name == "length" => {
                    offset += sz;
                }
                Field::Field {
                    name,
                    module,
                    rs_typ,
                    wire_sz: Expr::Value(sz),
                    r#enum,
                    mask,
                    is_fieldref,
                    is_prop_format,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    let fieldref_value = if *is_fieldref {
                        fieldref_get_value(name, params, info.has_prop_field, "self.")
                    } else {
                        None
                    };

                    let value_expr;

                    if let Some(value) = fieldref_value {
                        value_expr = format!("({} as {})", value, q_rs_typ);
                    } else if *is_prop_format {
                        value_expr = "P::FORMAT".to_string();
                    } else if mask.is_some() && rs_typ == "u32" {
                        value_expr = format!("self.{}.bits()", name);
                    } else if mask.is_some() {
                        value_expr = format!("(self.{}.bits() as {})", name, q_rs_typ);
                    } else if r#enum.is_some() && rs_typ == "u32" {
                        value_expr = format!("std::mem::transmute::<_, u32>(self.{})", name);
                    } else if r#enum.is_some() && rs_typ == "bool" {
                        value_expr = format!(
                            "(std::mem::transmute::<_, u32>(self.{}) as u{})",
                            name,
                            8 * sz
                        );
                    } else if r#enum.is_some() {
                        value_expr = format!(
                            "(std::mem::transmute::<_, u32>(self.{}) as {})",
                            name, q_rs_typ
                        );
                    } else if rs_typ == "bool" {
                        value_expr = format!(
                            "(if self.{} {{ 1u{} }} else {{ 0u{} }})",
                            name,
                            8 * sz,
                            8 * sz
                        );
                    } else {
                        value_expr = format!("self.{}", name);
                    }

                    writeln!(
                        out,
                        "{}{}.serialize(&mut buf{}[{} .. ]);",
                        cg::ind(2),
                        value_expr,
                        num,
                        offset
                    )?;

                    // if let Some(value) = fieldref_value {
                    //     writeln!(
                    //         out,
                    //         "{}({} as {}).serialize(&mut buf{}[{} .. ]);",
                    //         cg::ind(2),
                    //         value,
                    //         q_rs_typ,
                    //         num,
                    //         offset
                    //     )?;
                    // } else if (mask.is_some() || r#enum.is_some()) && rs_typ == "bool" {
                    //     writeln!(
                    //         out,
                    //         "{}*(buf{}.as_mut_ptr().add({}) as *mut {}) = std::mem::transmute::<_, u32>(self.{}) != 0;",
                    //         cg::ind(2), num, offset, q_rs_typ, name
                    //     )?;
                    // } else if mask.is_some() || r#enum.is_some() {
                    //     writeln!(
                    //         out,
                    //         "{}*(buf{}.as_mut_ptr().add({}) as *mut {}) = std::mem::transmute::<_, u32>(self.{}) as {};",
                    //         cg::ind(2), num, offset, q_rs_typ, name, q_rs_typ
                    //     )?;
                    // } else {
                    //     let (ptr_typ, postfix) = if rs_typ == "SendEventDest" {
                    //         ("u32", ".resource_id()")
                    //     } else {
                    //         (q_rs_typ.as_str(), "")
                    //     };
                    //     writeln!(
                    //         out,
                    //         "{}*(buf{}.as_mut_ptr().add({}) as *mut {}) = self.{}{};",
                    //         cg::ind(2),
                    //         num,
                    //         offset,
                    //         ptr_typ,
                    //         name,
                    //         postfix
                    //     )?;
                    // }
                    offset += sz;
                }
                Field::List {
                    name,
                    module,
                    rs_typ,
                    wire_sz: Expr::Value(sz),
                    len_expr: Expr::Value(len),
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    writeln!(out, "{}std::slice::from_raw_parts_mut(", cg::ind(2))?;
                    writeln!(
                        out,
                        "{}    buf{}.as_mut_ptr().add({}) as *mut {}, {}",
                        cg::ind(2),
                        num,
                        offset,
                        q_rs_typ,
                        len
                    )?;
                    writeln!(out, "{}).copy_from_slice(&self.{});", cg::ind(2), name)?;

                    offset += sz;
                }
                Field::Expr {
                    name,
                    typ,
                    expr,
                    wire_sz: Expr::Value(sz),
                    ..
                } if typ == "BOOL" => {
                    writeln!(out, "{}// {} expression", cg::ind(2), name)?;
                    writeln!(
                        out,
                        "{}*(buf{}.as_mut_ptr().add({}) as *mut u8) = {} as u8;",
                        cg::ind(2),
                        num,
                        offset,
                        // bad hack, but only one occurence of exprfield in the complete library
                        // no need to push further
                        self.build_rs_expr(expr, "self.", "", &[])
                            .replace("_len", ".len()"),
                    )?;
                    offset += sz;
                }
                Field::Pad {
                    wire_sz: Expr::Value(sz),
                    ..
                } => {
                    offset += sz;
                }
                _ => unreachable!("{:#?}", f),
            }
        }
        writeln!(
            out,
            "{}sections[{}].iov_base = buf{}.as_mut_ptr() as *mut _;",
            cg::ind(2),
            num * 2 + 2,
            num
        )?;
        writeln!(
            out,
            "{}sections[{}].iov_len = {};",
            cg::ind(2),
            num * 2 + 2,
            sz
        )?;
        Ok(())
    }

    fn emit_req_var_buf<O: Write>(&self, out: &mut O, num: usize, field: &Field) -> io::Result<()> {
        match field {
            Field::Field {
                name,
                struct_style: Some(StructStyle::DynBuf),
                ..
            } => {
                writeln!(
                    out,
                    "{}sections[{}].iov_base = self.{}.wire_ptr() as *mut _;",
                    cg::ind(2),
                    num * 2 + 2,
                    name,
                )?;
                writeln!(
                    out,
                    "{}sections[{}].iov_len = self.{}.wire_len();",
                    cg::ind(2),
                    num * 2 + 2,
                    name,
                )?;
            }
            Field::List {
                name,
                struct_style: Some(StructStyle::DynBuf),
                ..
            } => {
                writeln!(
                    out,
                    "{}let len{}: usize = self.{}.iter().map(|el| el.wire_len()).sum();",
                    cg::ind(2),
                    num,
                    name
                )?;
                writeln!(
                    out,
                    "{}let mut buf{} = vec![0u8; len{}];",
                    cg::ind(2),
                    num,
                    num
                )?;
                writeln!(out, "{}let mut offset = 0usize;", cg::ind(2))?;
                writeln!(out, "{}for el in self.{} {{", cg::ind(2), name)?;
                writeln!(
                    out,
                    "{}    offset += el.serialize(&mut buf{}[offset..]);",
                    cg::ind(2),
                    num
                )?;
                writeln!(out, "{}}}", cg::ind(2))?;
                writeln!(
                    out,
                    "{}sections[{}].iov_base = buf{}.as_ptr() as *mut _;",
                    cg::ind(2),
                    num * 2 + 2,
                    num
                )?;
                writeln!(
                    out,
                    "{}sections[{}].iov_len = buf{}.len();",
                    cg::ind(2),
                    num * 2 + 2,
                    num
                )?;
            }
            Field::List { name, rs_typ, .. } if rs_typ == "char" => {
                writeln!(
                    out,
                    "{}sections[{}].iov_base = self.{}.as_ptr() as *mut _;",
                    cg::ind(2),
                    num * 2 + 2,
                    name
                )?;
                writeln!(
                    out,
                    "{}sections[{}].iov_len = self.{}.len();",
                    cg::ind(2),
                    num * 2 + 2,
                    name
                )?;
            }
            Field::List {
                name,
                module,
                rs_typ,
                ..
            } => {
                let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                writeln!(
                    out,
                    "{}sections[{}].iov_base = self.{}.as_ptr() as *mut _;",
                    cg::ind(2),
                    num * 2 + 2,
                    name,
                )?;
                writeln!(
                    out,
                    "{}sections[{}].iov_len = self.{}.len() * std::mem::size_of::<{}>();",
                    cg::ind(2),
                    num * 2 + 2,
                    name,
                    q_rs_typ,
                )?;
            }
            Field::Switch { name, .. } => {
                writeln!(
                    out,
                    "{}let len{} = self.{}.wire_len();",
                    cg::ind(2),
                    num,
                    name,
                )?;
                writeln!(
                    out,
                    "{}let mut buf{} = vec![0u8; len{}];",
                    cg::ind(2),
                    num,
                    num
                )?;
                writeln!(
                    out,
                    "{}self.{}.serialize(&mut buf{});",
                    cg::ind(2),
                    name,
                    num
                )?;
                writeln!(
                    out,
                    "{}sections[{}].iov_base = buf{}.as_ptr() as *mut _;",
                    cg::ind(2),
                    num * 2 + 2,
                    num
                )?;
                writeln!(
                    out,
                    "{}sections[{}].iov_len = buf{}.len();",
                    cg::ind(2),
                    num * 2 + 2,
                    num
                )?;
            }
            _ => unreachable!("{:#?}", field),
        }
        Ok(())
    }

    fn fixed_fields_size(&self, fields: &[Field]) -> usize {
        let mut sz = 0;
        for f in fields {
            match f {
                Field::Field {
                    wire_sz: Expr::Value(s),
                    ..
                } => {
                    sz += s;
                }
                Field::List {
                    wire_sz: Expr::Value(s),
                    ..
                } => {
                    sz += s;
                }
                Field::Expr {
                    wire_sz: Expr::Value(s),
                    ..
                } => {
                    sz += s;
                }
                Field::Pad {
                    wire_sz: Expr::Value(s),
                    ..
                } => {
                    sz += s;
                }
                _ => unreachable!("{:#?}", f),
            }
        }
        sz
    }
}

#[derive(Debug)]
struct RequestInfo<'a> {
    rs_typ: String,
    cookie_rs_typ: String,
    reply_rs_typ: String,
    sections: Vec<SerializeSection<'a>>,
    has_lifetime: bool,
    opcode: u32,
    is_void: bool,
    has_prop_field: bool,
}

#[derive(Debug)]
enum SerializeSection<'a> {
    Fixed(&'a [Field]),
    Var(&'a Field),
}

// When we encounter a field that is referred in eg a list len or switch mask
// we try to infer its value from the list or the switch.
// But we can manage this only for the simplest cases:
//    - a single fieldref
//    - a fieldref multiplied by format divided by 8 (for properties only)
// For other cases, we put the field as public paramater and require user to supply a value.
fn request_fieldref_emitted(name: &str, fields: &[Field], has_prop_field: bool) -> bool {
    for f in fields {
        match f {
            Field::List {
                len_expr: Expr::FieldRef(fr),
                ..
            } if fr == name => {
                return false;
            }
            Field::List {
                len_expr: Expr::Op(op, lhs, rhs),
                ..
            } if has_prop_field && op == "*" && is_prop_field_mult(name, lhs, rhs) => {
                return false;
            }
            Field::Switch {
                expr: Expr::FieldRef(fr),
                ..
            } if fr == name => {
                return false;
            }
            _ => {}
        }
    }
    true
}

fn is_prop_field_mult<'a>(name: &'a str, lhs: &Expr, rhs: &Expr) -> bool {
    // we are in the first level of the multiplication `length * (format / 8)`
    // must reach 4 conditions:
    // - lhs is fieldref to name
    // - rhs is a division
    // - rhs::lhs is fieldref format
    // - rhs::rhs is value 8
    // box pattern matching would really be helpful, but not stabilized at time of coding

    if !matches!(lhs, Expr::FieldRef(f) if f == name) {
        return false;
    }

    match rhs {
        Expr::Op(op, lhs, rhs) if op == "/" => {
            if !matches!(&**lhs, Expr::FieldRef(f) if f == "format") {
                return false;
            }
            if !matches!(&**rhs, Expr::Value(8)) {
                return false;
            }
        }
        _ => return false,
    }

    true
}

fn fieldref_get_value(
    name: &str,
    fields: &[Field],
    has_prop_field: bool,
    acc: &str,
) -> Option<String> {
    for f in fields {
        match f {
            Field::List {
                name: fname,
                len_expr: Expr::FieldRef(fr),
                ..
            } if fr == name => {
                return Some(format!("{}{}.len()", acc, fname));
            }
            Field::List {
                name: fname,
                len_expr: Expr::Op(op, lhs, rhs),
                ..
            } if has_prop_field && op == "*" && is_prop_field_mult(name, lhs, rhs) => {
                return Some(format!("{}{}.len()", acc, fname));
            }
            Field::Switch {
                name: fname,
                module,
                rs_typ,
                expr: Expr::FieldRef(fr),
                is_mask,
                ..
            } if fr == name => {
                let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                if *is_mask {
                    return Some(format!("{}::get_mask({}{}).bits()", q_rs_typ, acc, fname));
                } else {
                    return Some(format!(
                        "std::mem::transmute::<_, u32>({}{}.get_enum())",
                        acc, fname
                    ));
                }
            }
            _ => {}
        }
    }
    None
}

use crate::cg;
use crate::cg::util;
use crate::ir;

use super::{
    doc::DocField, CodeGen, Doc, Expr, Field, HasWireLayout, QualifiedRsTyp, RsTyp, StructStyle,
    TypeInfo, WireSz,
};

use std::io::{self, Write};

/// struct of external parameters passed to functions such as compute_len
/// This is very often `()` for which `None` is used, but sometimes an field external to struct is needed
/// to compute the len of a list (i.e. <paramref> element types)
#[derive(Clone, Debug)]
pub(super) struct ParamsStruct {
    pub rs_typ: String,
    pub params: Vec<String>,
}

impl ParamsStruct {
    pub fn emit<O: Write>(&self, out: &mut O) -> io::Result<()> {
        writeln!(out)?;
        writeln!(out, "#[derive(Copy, Clone, Debug)]")?;
        writeln!(out, "pub struct {} {{", self.rs_typ)?;
        for p in &self.params {
            writeln!(out, "    pub {}: usize,", p)?;
        }
        writeln!(out, "}}")?;
        Ok(())
    }
}

impl RsTyp for Option<&ParamsStruct> {
    fn rs_typ(&self) -> &str {
        match self {
            Some(params_struct) => &params_struct.rs_typ,
            _ => "()",
        }
    }
}

#[derive(Debug)]
pub(super) struct ResolvedFields {
    pub fields: Vec<Field>,
    pub wire_sz: Expr,
    pub has_wire_layout: bool,
    pub unresolved_fieldrefs: Vec<String>,
    pub params_struct: Option<ParamsStruct>,
}

impl CodeGen {
    pub(super) fn resolve_struct(
        &mut self,
        typ: &str,
        fields: &[ir::Field],
        doc: &Option<ir::Doc>,
    ) {
        let rs_typ = cg::rust_type_name(typ);
        let doc = self.resolve_doc(doc.clone());
        let ResolvedFields {
            fields,
            wire_sz,
            has_wire_layout,
            params_struct,
            // unresolved_fieldrefs,
            ..
        } = self.resolv_struct_fields(&rs_typ, "", fields, doc.as_ref());

        // assert!(unresolved_fieldrefs.is_empty());

        let typ_info = TypeInfo::Struct {
            module: None,
            rs_typ,
            fields,
            wire_sz,
            has_wire_layout,
            params_struct,
            doc,
        };
        self.register_typ(typ.to_string(), typ_info);
    }

    pub(super) fn resolv_struct_fields(
        &mut self,
        struct_rs_typ: &str,
        parent_switch: &str,
        fields: &[ir::Field],
        doc: Option<&Doc>,
    ) -> ResolvedFields {
        let mut vec = Vec::new();
        let mut wire_off = Expr::Value(0usize);
        let mut has_wire_layout = true;
        let mut need_compute_offset = false;
        // fields that are referenced in list length of this struct
        let mut fieldrefs = Vec::new();
        // external fields that are refereced in list length of this struct
        let mut paramrefs = Vec::new();
        // fields of this struct that are used as list length of other struct
        let mut paramfields = Vec::new();
        let mut unresolved_fieldrefs = Vec::new();

        let has_prop_field = fields.iter().any(
            |f| matches!(f, ir::Field::Field{name, typ, ..} if name == "format" && typ == "CARD8"),
        ) && fields
            .iter()
            .any(|f| matches!(f, ir::Field::List{typ, ..} if typ == "void"));

        for f in fields {
            let f_sz = match f {
                ir::Field::Field {
                    name,
                    typ,
                    r#enum,
                    mask,
                    ..
                } => {
                    let FieldInfo {
                        name,
                        module,
                        rs_typ,
                        wire_sz,
                        has_wire_layout: hfl,
                        struct_style,
                        is_union,
                        is_xid,
                        is_mask,
                        params_struct,
                        doc,
                        ..
                    } = self.get_field_info(name, typ, r#enum.is_some(), doc);

                    if !hfl || (rs_typ != "u32" && (r#enum.is_some() || (mask.is_some()))) {
                        has_wire_layout = false;
                    }

                    let r#enum = r#enum.as_ref().map(|typ| self.get_mod_rs_typ(typ));
                    let mask = mask.as_ref().map(|typ| self.get_mod_rs_typ(typ));

                    let wire_sz = wire_sz.reduce();

                    let is_prop_format = has_prop_field && name == "format";

                    vec.push(Field::Field {
                        name,
                        module,
                        rs_typ,
                        wire_off: wire_off.clone(),
                        wire_sz: wire_sz.clone(),
                        struct_style,
                        params_struct,
                        doc,
                        is_mask: is_mask || mask.is_some(),
                        r#enum,
                        mask,
                        is_fieldref: false,
                        is_paramref: false,
                        is_copy: hfl,
                        is_union,
                        is_xid,
                        need_compute_offset,
                        is_prop_format,
                    });
                    wire_sz
                }
                ir::Field::Pad(wire_sz) => {
                    has_wire_layout = false;
                    let wire_off = wire_off.clone().reduce();
                    vec.push(Field::Pad {
                        wire_off,
                        wire_sz: Expr::Value(*wire_sz),
                    });
                    Expr::Value(*wire_sz)
                }
                ir::Field::AlignPad(sz) => {
                    has_wire_layout = false;
                    let wire_off = wire_off.clone().reduce();
                    let wire_sz = Expr::AlignPad(*sz, Box::new(wire_off.clone())).reduce();
                    vec.push(Field::AlignPad {
                        wire_off,
                        wire_sz: wire_sz.clone(),
                    });
                    wire_sz
                }
                ir::Field::List {
                    name,
                    typ,
                    len_expr,
                } => {
                    let FieldInfo {
                        name,
                        module,
                        mut rs_typ,
                        typ,
                        wire_sz,
                        has_wire_layout: hfl,
                        struct_style,
                        params_struct,
                        doc,
                        ..
                    } = self.get_field_info(name, typ, false, doc);

                    let len_expr = self.resolve_expr(len_expr);

                    wire_sz.fetch_paramrefs_owned(&mut paramfields);

                    let wire_sz = Expr::Op(
                        "*".to_string(),
                        Box::new(len_expr.clone()),
                        Box::new(wire_sz),
                    );
                    let wire_sz = wire_sz.reduce();

                    let fixed_str = matches!((rs_typ.as_str(), &wire_sz), ("char", Expr::Value(_)));
                    if fixed_str {
                        rs_typ = "u8".into();
                    } else if !hfl || !matches!(wire_sz, Expr::Value(_)) {
                        has_wire_layout = false;
                    }

                    len_expr.fetch_fieldrefs_owned(&mut fieldrefs);
                    len_expr.fetch_paramrefs_owned(&mut paramrefs);

                    // assert!(!need_compute_offset, "{}::{}", self.xcb_mod, name);
                    let is_prop = has_prop_field && typ == "void";

                    vec.push(Field::List {
                        name,
                        module,
                        rs_typ,
                        wire_off: wire_off.clone(),
                        wire_sz: wire_sz.clone(),
                        struct_style,
                        is_fieldref: false,
                        len_expr,
                        need_compute_offset,
                        params_struct,
                        is_prop,
                        doc,
                    });

                    if let Some(StructStyle::DynBuf) = struct_style {
                        need_compute_offset = true;
                    }

                    wire_sz
                }
                ir::Field::ListNoLen { typ, name } => {
                    let FieldInfo {
                        name,
                        module,
                        rs_typ,
                        typ,
                        struct_style,
                        params_struct,
                        doc,
                        ..
                    } = self.get_field_info(name, typ, false, doc);

                    has_wire_layout = false;
                    let is_prop = has_prop_field && typ == "void";

                    vec.push(Field::List {
                        name,
                        module,
                        rs_typ,
                        wire_off: wire_off.clone(),
                        wire_sz: Expr::UntilEnd,
                        struct_style,
                        params_struct,
                        is_fieldref: false,
                        len_expr: Expr::UntilEnd,
                        need_compute_offset,
                        is_prop,
                        doc,
                    });

                    Expr::Unknown("list no len".to_string())
                }
                ir::Field::ValueParam { .. } => {
                    unreachable!("<valueparam> not anymore used with xcb-1.14")
                }
                ir::Field::Switch(name, expr, cases) => {
                    let expr = self.resolve_expr(expr);
                    let field = self.resolve_switch(
                        struct_rs_typ,
                        parent_switch,
                        name,
                        &expr,
                        &wire_off,
                        cases,
                        &mut vec,
                        need_compute_offset,
                    );
                    expr.fetch_fieldrefs_owned(&mut fieldrefs);
                    if let Field::Switch { params_struct, .. } = &field {
                        let mut params = params_struct.params.clone();
                        fieldrefs.append(&mut params);
                    } else {
                        unreachable!();
                    };
                    vec.push(field);
                    need_compute_offset = true;
                    has_wire_layout = false;
                    Expr::Unknown("switch len".to_string())
                }
                ir::Field::Expr { name, typ, expr } => {
                    let FieldInfo {
                        name, typ, wire_sz, ..
                    } = self.get_field_info(name, typ, false, doc);

                    has_wire_layout = false;

                    let wire_sz = wire_sz.reduce();
                    let expr = self.resolve_expr(expr);

                    vec.push(Field::Expr {
                        name,
                        typ,
                        wire_off: wire_off.clone(),
                        wire_sz: wire_sz.clone(),
                        expr,
                    });
                    wire_sz
                }
                ir::Field::Fd(name) => {
                    eprintln!("partial treatment of Fd field: {}::{}", struct_rs_typ, name);
                    let doc = self.doc_lookup_field(doc, name);

                    vec.push(Field::Field {
                        name: name.clone(),
                        module: None,
                        rs_typ: "RawFd".to_string(),
                        wire_off: wire_off.clone(),
                        wire_sz: Expr::Value(4),
                        struct_style: None,
                        params_struct: None,
                        doc,
                        is_fieldref: false,
                        is_paramref: false,
                        is_copy: true,
                        is_union: false,
                        is_xid: false,
                        is_mask: false,
                        r#enum: None,
                        mask: None,
                        need_compute_offset: false,
                        is_prop_format: false,
                    });
                    has_wire_layout = false;
                    Expr::Value(4)
                } // f => unreachable!("{:#?}", f),
            };

            let new_off = Expr::Op("+".to_string(), Box::new(wire_off), Box::new(f_sz));
            wire_off = new_off.reduce();
        }

        for fr in fieldrefs {
            let mut resolved = false;
            for f in &mut vec {
                match f {
                    Field::Field {
                        name, is_fieldref, ..
                    } if name == &fr => {
                        *is_fieldref = true;
                        resolved = true;
                        break;
                    }
                    Field::List {
                        name, is_fieldref, ..
                    } if name == &fr => {
                        *is_fieldref = true;
                        resolved = true;
                        break;
                    }
                    _ => {}
                }
            }
            if !resolved {
                unresolved_fieldrefs.push(fr);
            }
        }
        for pf in &paramfields {
            for f in &mut vec {
                match f {
                    Field::Field {
                        name, is_paramref, ..
                    } if name == pf => {
                        *is_paramref = true;
                        break;
                    }
                    _ => {}
                }
            }
        }
        let params_struct = if paramrefs.is_empty() {
            None
        } else {
            Some(ParamsStruct {
                rs_typ: struct_rs_typ.to_string() + "Params",
                params: paramrefs,
            })
        };

        ResolvedFields {
            fields: vec,
            wire_sz: wire_off,
            has_wire_layout,
            unresolved_fieldrefs,
            params_struct,
        }
    }

    fn get_mod_rs_typ(&self, typ: &str) -> (Option<String>, String) {
        let (module, typ) = util::extract_module(typ);
        let typinfo = self.find_typinfo(module, typ);
        let module = typinfo.module();
        let rs_typ = typinfo.rs_typ();
        (module.map(str::to_owned), rs_typ.to_string())
    }

    fn get_field_info(
        &self,
        name: &str,
        typ: &str,
        alt_repr: bool,
        doc: Option<&Doc>,
    ) -> FieldInfo {
        let name = cg::rust_field_name(name);
        let (module, typ) = util::extract_module(typ);
        let typinfo = self.find_typinfo(module, typ);
        let module = typinfo.module();
        let rs_typ = typinfo.rs_typ();
        let wire_sz = typinfo.wire_sz();
        let is_union = matches!(typinfo, TypeInfo::Union { .. } | TypeInfo::XidUnion { .. });
        let is_xid = matches!(typinfo, TypeInfo::Xid { .. } | TypeInfo::XidUnion { .. });
        let is_mask = matches!(typinfo, TypeInfo::Mask { .. });
        let params_struct = match typinfo {
            TypeInfo::Struct { params_struct, .. } => params_struct.clone(),
            _ => None,
        };
        let doc = self.doc_lookup_field(doc, &name);

        FieldInfo {
            name,
            module: module.map(str::to_owned),
            typ: typ.to_string(),
            rs_typ: rs_typ.to_string(),
            wire_sz,
            has_wire_layout: !alt_repr && typinfo.has_wire_layout(),
            struct_style: typinfo.struct_style(),
            params_struct,
            doc,
            is_union,
            is_xid,
            is_mask,
        }
    }

    fn build_params_expr(
        &self,
        params_struct: Option<&ParamsStruct>,
        module: Option<&str>,
        acc_pref: &str,
        acc_post: &str,
    ) -> String {
        if params_struct.is_none() {
            return "()".to_string();
        }
        let params_struct = params_struct.unwrap();
        let q_rs_typ = (module, params_struct.rs_typ.as_str()).qualified_rs_typ();
        let mut expr = q_rs_typ + " {";
        for (i, p) in params_struct.params.iter().enumerate() {
            expr.push_str(&format!("{}: {}{}{} as usize", p, acc_pref, p, acc_post));
            if i < params_struct.params.len() - 1 {
                expr.push_str(", ");
            }
        }
        expr.push('}');
        expr
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn emit_struct<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        fields: &[Field],
        wire_sz: &Expr,
        has_wire_layout: bool,
        params_struct: Option<&ParamsStruct>,
        doc: Option<&Doc>,
    ) -> io::Result<()> {
        if !self.rs_typ_is_needed(rs_typ) {
            return Ok(());
        }

        match (has_wire_layout, wire_sz) {
            (true, Expr::Value(wire_sz)) => {
                self.emit_wire_layout_struct(out, rs_typ, fields, *wire_sz, doc)?
            }
            (false, Expr::Value(wire_sz)) => {
                self.emit_fix_buf_struct(out, rs_typ, fields, *wire_sz, doc)?
            }
            (false, _) => self.emit_dyn_buf_struct(out, rs_typ, fields, params_struct, doc)?,
            _ => unreachable!("{}::{}", self.xcb_mod, rs_typ),
        }

        Ok(())
    }

    fn emit_wire_layout_struct<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        fields: &[Field],
        wire_sz: usize,
        doc: Option<&Doc>,
    ) -> io::Result<()> {
        writeln!(out)?;
        if let Some(doc) = doc {
            doc.emit(out, 0)?;
        }
        writeln!(out, "#[derive(Copy, Clone, Debug)]")?;
        writeln!(out, "#[repr(C)]")?;
        writeln!(out, "pub struct {} {{", rs_typ)?;
        for f in fields {
            match f {
                Field::Field {
                    name,
                    module,
                    rs_typ,
                    r#enum,
                    mask,
                    doc,
                    ..
                } => {
                    let q_rs_typ = enum_mask_qualified_rs_typ(module, rs_typ, r#enum, mask);
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "    pub {}: {},", name, q_rs_typ)?;
                }
                Field::List {
                    name,
                    module,
                    rs_typ,
                    len_expr: Expr::Value(len),
                    doc,
                    ..
                } => {
                    let mod_rs_typ = (module, rs_typ);
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(
                        out,
                        "    pub {}: [{}; {}],",
                        name,
                        mod_rs_typ.qualified_rs_typ(),
                        len
                    )?;
                }
                _ => unreachable!("emitting struct field {:?}", f),
            }
        }
        writeln!(out, "}}")?;

        self.emit_sizeof_test(out, rs_typ, wire_sz)?;

        writeln!(out)?;
        writeln!(out, "impl base::Wired for {} {{", rs_typ)?;
        writeln!(out, "    type Params = ();")?;
        writeln!(
            out,
            "    unsafe fn compute_wire_len(_ptr: *const u8, _params: ()) -> usize {{ {} }}",
            wire_sz
        )?;
        writeln!(out)?;
        writeln!(out, "    fn wire_len(&self) -> usize {{ {} }}", wire_sz)?;
        writeln!(out)?;
        writeln!(
            out,
            "    fn serialize(&self, wire_buf: &mut [u8]) -> usize {{"
        )?;
        writeln!(out, "        let me = unsafe {{")?;
        writeln!(
            out,
            "            std::slice::from_raw_parts(self as *const {} as _, {})",
            rs_typ, wire_sz
        )?;
        writeln!(out, "        }};")?;
        writeln!(out, "        wire_buf.copy_from_slice(me);")?;
        writeln!(out, "        {}", wire_sz)?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        Ok(())
    }

    fn emit_fix_buf_struct<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        fields: &[Field],
        wire_sz: usize,
        doc: Option<&Doc>,
    ) -> io::Result<()> {
        writeln!(out)?;
        if let Some(doc) = doc {
            doc.emit(out, 0)?;
        }
        writeln!(out, "#[derive(Copy, Clone)]")?;
        writeln!(out, "pub struct {} {{", rs_typ)?;
        writeln!(out, "    data: [u8; {}],", wire_sz)?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "#[allow(unused_parens)]")?;
        writeln!(out, "impl {} {{", rs_typ)?;
        writeln!(
            out,
            "    pub(crate) unsafe fn from_data<D: AsRef<[u8]> + ?Sized>(data: &D) -> &{} {{",
            rs_typ
        )?;
        writeln!(
            out,
            "        debug_assert_eq!(data.as_ref().len(), {});",
            wire_sz
        )?;
        writeln!(
            out,
            "        &*(data.as_ref() as *const [u8] as *const {})",
            rs_typ
        )?;
        writeln!(out, "    }}")?;

        writeln!(out)?;
        writeln!(
            out,
            "    fn wire_ptr(&self) -> *const u8 {{ self.data.as_ptr() }}"
        )?;

        writeln!(out)?;
        writeln!(out, "    fn wire_len(&self) -> usize {{ self.data.len() }}")?;

        self.emit_struct_accessors(out, rs_typ, fields)?;

        writeln!(out, "}}")?;

        self.emit_sizeof_test(out, rs_typ, wire_sz)?;

        writeln!(out)?;
        writeln!(out, "impl base::Wired for {} {{", rs_typ)?;
        writeln!(out, "    type Params = ();")?;
        writeln!(
            out,
            "    unsafe fn compute_wire_len(_ptr: *const u8, _params: ()) -> usize {{ {} }}",
            wire_sz
        )?;
        writeln!(out)?;
        writeln!(out, "    fn wire_len(&self) -> usize {{ {} }}", wire_sz)?;
        writeln!(out)?;
        writeln!(
            out,
            "    fn serialize(&self, wire_buf: &mut [u8]) -> usize {{"
        )?;
        writeln!(out, "        wire_buf.copy_from_slice(&self.data);")?;
        writeln!(out, "        self.data.len()")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        self.emit_debug_impl(out, rs_typ, fields)?;

        Ok(())
    }

    fn emit_dyn_buf_struct<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        fields: &[Field],
        params_struct: Option<&ParamsStruct>,
        doc: Option<&Doc>,
    ) -> io::Result<()> {
        if let Some(params_struct) = params_struct {
            params_struct.emit(out)?;
        }
        writeln!(out)?;
        if let Some(doc) = doc {
            doc.emit(out, 0)?;
        }
        writeln!(out, "pub struct {} {{", rs_typ)?;
        writeln!(out, "    data: [u8],")?;
        writeln!(out, "}}")?;
        writeln!(out)?;
        writeln!(out, "#[allow(unused_parens)]")?;
        writeln!(out, "impl {} {{", rs_typ)?;
        writeln!(
            out,
            "    pub(crate) unsafe fn from_data<D: AsRef<[u8]> + ?Sized>(data: &D) -> &{} {{",
            rs_typ
        )?;
        if params_struct.is_none() {
            writeln!(
                out,
                "        debug_assert_eq!(data.as_ref().len(), {}::compute_wire_len(data.as_ref().as_ptr(), ()));",
                rs_typ
            )?;
        }
        writeln!(
            out,
            "        &*(data.as_ref() as *const [u8] as *const {})",
            rs_typ
        )?;
        writeln!(out, "    }}")?;

        writeln!(out)?;
        writeln!(
            out,
            "    fn wire_ptr(&self) -> *const u8 {{ self.data.as_ptr() }}"
        )?;

        let compute_wire_len_stmts =
            self.emit_compute_offset_and_get_stmts(out, rs_typ, fields, params_struct)?;
        self.emit_struct_accessors(out, rs_typ, fields)?;

        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "impl base::Wired for {} {{", rs_typ)?;
        writeln!(out, "    type Params = {};", params_struct.rs_typ())?;
        self.emit_compute_func(
            out,
            "compute_wire_len",
            params_struct,
            &compute_wire_len_stmts,
        )?;
        writeln!(out)?;
        writeln!(out, "    fn wire_len(&self) -> usize {{ self.data.len() }}")?;
        writeln!(out)?;
        writeln!(
            out,
            "    fn serialize(&self, wire_buf: &mut [u8]) -> usize {{"
        )?;
        writeln!(out, "        wire_buf.copy_from_slice(&self.data);")?;
        writeln!(out, "        self.data.len()")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "#[derive(Clone)]")?;
        writeln!(out, "pub struct {}Buf {{", rs_typ)?;
        writeln!(out, "    data: Vec<u8>,")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "impl {}Buf {{", rs_typ)?;
        writeln!(
            out,
            "    pub(crate) unsafe fn from_data(data: Vec<u8>) -> {}Buf {{",
            rs_typ
        )?;
        if params_struct.is_none() {
            writeln!(
                out,
                "        debug_assert_eq!({}::compute_wire_len(data.as_ptr(), ()), data.len());",
                rs_typ
            )?;
        }
        writeln!(out, "        {}Buf {{ data }}", rs_typ)?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "impl std::ops::Deref for {}Buf {{", rs_typ)?;
        writeln!(out, "    type Target = {};", rs_typ)?;
        writeln!(out, "    fn deref(&self) -> &Self::Target {{")?;
        writeln!(
            out,
            "        unsafe {{ {}::from_data(&self.data) }}",
            rs_typ
        )?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(
            out,
            "impl std::borrow::Borrow<{}> for {}Buf {{",
            rs_typ, rs_typ
        )?;
        writeln!(out, "    fn borrow(&self) -> &{} {{", rs_typ)?;
        writeln!(
            out,
            "        unsafe {{ {}::from_data(&self.data) }}",
            rs_typ
        )?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "impl std::borrow::ToOwned for {} {{", rs_typ)?;
        writeln!(out, "    type Owned = {}Buf;", rs_typ)?;
        writeln!(out, "    fn to_owned(&self) -> Self::Owned {{")?;
        writeln!(out, "        {}Buf {{", rs_typ)?;
        writeln!(out, "            data: self.data.to_vec()")?;
        writeln!(out, "        }}")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        self.emit_debug_impl(out, rs_typ, fields)?;
        self.emit_debug_impl(out, &(rs_typ.to_string() + "Buf"), fields)?;

        self.emit_dyn_buf_struct_iterator(out, rs_typ, params_struct)?;

        Ok(())
    }

    pub(super) fn field_compute_len_stmts(
        &self,
        field: &Field,
        stmts: &mut Vec<String>,
        struct_offset: &Expr,
    ) {
        let struct_offset = if let Expr::Value(0) = struct_offset {
            String::new()
        } else {
            self.build_rs_expr(struct_offset, "", "", &[]) + " + "
        };
        match field {
            Field::Field {
                name,
                struct_style: Some(StructStyle::DynBuf),
                params_struct,
                module,
                rs_typ,
                ..
            } => {
                let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                let params_expr = self.build_params_expr(
                    params_struct.as_ref(),
                    module.as_ref().map(|s| s.as_str()),
                    "",
                    "",
                );
                stmts.push(format!("// {}", name));
                stmts.push(format!(
                    "sz += {}::compute_wire_len(ptr.add({}sz), {});",
                    q_rs_typ, struct_offset, params_expr
                ));
            }
            Field::Field {
                wire_sz,
                name,
                is_fieldref,
                is_paramref,
                rs_typ,
                ..
            } => {
                stmts.push(format!("// {}", name));

                if *is_fieldref || *is_paramref {
                    stmts.push(format!(
                        "let {} = *(ptr.add({}sz) as *const {});",
                        name, struct_offset, rs_typ
                    ));
                }

                stmts.push(format!(
                    "sz += {};",
                    self.build_rs_expr(wire_sz, "", "", &[])
                ));
            }
            Field::List {
                name,
                len_expr,
                module,
                rs_typ,
                struct_style: Some(StructStyle::DynBuf),
                params_struct,
                is_fieldref,
                ..
            } => {
                let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                stmts.push(format!("// {}", name));
                if *is_fieldref {
                    stmts.push(format!("let mut {} = Vec::new();", name));
                }
                stmts.push(format!(
                    "for _ in 0 .. {} {{",
                    self.build_rs_expr(len_expr, "", "", &[])
                ));
                let params_expr = self.build_params_expr(
                    params_struct.as_ref(),
                    module.as_ref().map(|s| s.as_str()),
                    "",
                    "",
                );
                if *is_fieldref {
                    stmts.push(format!(
                        "    let len = {}::compute_wire_len(ptr.add({}sz), {});",
                        q_rs_typ, struct_offset, params_expr
                    ));
                    stmts.push(format!(
                        "    let data = std::slice::from_raw_parts(ptr.add({}sz), len);",
                        struct_offset
                    ));
                    stmts.push(format!("    {}.push({}::from_data(data));", name, q_rs_typ));
                    stmts.push("    sz += len;".to_string());
                } else {
                    stmts.push(format!(
                        "    sz += {}::compute_wire_len(ptr.add({}sz), {});",
                        q_rs_typ, struct_offset, params_expr
                    ));
                }
                stmts.push("}".to_string());
            }
            Field::List {
                name,
                wire_sz,
                is_fieldref,
                len_expr,
                module,
                rs_typ,
                ..
            } => {
                let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                stmts.push(format!("// {}", name));
                if *is_fieldref {
                    stmts.push(format!("let {} = {{", name));
                    stmts.push(format!(
                        "    let len = {};",
                        self.build_rs_expr(len_expr, "", "", &[])
                    ));
                    stmts.push(format!(
                        "    let data = ptr.add({}sz) as *const {};",
                        struct_offset, q_rs_typ
                    ));
                    stmts.push(format!(
                        "    sz += len * std::mem::size_of::<{}>();",
                        q_rs_typ
                    ));
                    stmts.push("    std::slice::from_raw_parts(data, len)".to_string());
                    stmts.push("};".to_string());
                } else {
                    stmts.push(format!(
                        "sz += {};",
                        self.build_rs_expr(wire_sz, "", "", &[])
                    ));
                }
            }
            Field::Switch {
                name,
                module,
                rs_typ,
                params_struct,
                is_mask,
                ..
            } => {
                let params_expr = self.build_params_expr(
                    Some(params_struct),
                    module.as_ref().map(|m| m.as_str()),
                    "",
                    "",
                );
                let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                let impl_type = if *is_mask {
                    format!("<&[{}]>", q_rs_typ)
                } else {
                    q_rs_typ
                };
                stmts.push(format!("// {}", name));
                stmts.push(format!(
                    "sz += {}::compute_wire_len(ptr.add({}sz), {});",
                    impl_type, struct_offset, params_expr
                ));
            }
            Field::Pad { wire_sz, .. } => {
                stmts.push("// pad".to_string());
                stmts.push(format!(
                    "sz += {};",
                    self.build_rs_expr(wire_sz, "", "", &[])
                ));
            }
            Field::AlignPad {
                wire_sz: Expr::AlignPad(align, _),
                ..
            } => {
                stmts.push("// align pad".to_string());
                stmts.push(format!("sz += base::align_pad(sz, {});", align));
            }
            f => unreachable!("missed handling of field in compute_wire_len: {:?}", f),
        }
    }

    pub(super) fn emit_compute_func<O: Write>(
        &self,
        out: &mut O,
        fname: &str,
        params_struct: Option<&ParamsStruct>,
        stmts: &[String],
    ) -> io::Result<()> {
        writeln!(out)?;
        writeln!(
            out,
            "    unsafe fn {}(ptr: *const u8, {}params: {}) -> usize {{",
            fname,
            if params_struct.is_none() { "_" } else { "" },
            params_struct.rs_typ(),
        )?;
        if let Some(params_struct) = params_struct {
            writeln!(out, "        let {} {{", params_struct.rs_typ)?;
            for p in &params_struct.params {
                writeln!(out, "{}{},", cg::ind(3), p)?;
            }
            writeln!(out, "        }} = params;")?;
        }
        for s in stmts {
            writeln!(out, "        {}", s)?;
        }
        writeln!(out, "        sz")?;
        writeln!(out, "    }}")?;
        Ok(())
    }

    /// Get the statements for each field size calculation, and emit offset function
    /// each time we hit a field that requires an offset function.
    /// The resulting statements can be used to emit the compute_wire_len function
    pub(super) fn emit_compute_offset_and_get_stmts<O: Write>(
        &self,
        out: &mut O,
        _struct_rs_typ: &str,
        fields: &[Field],
        params_struct: Option<&ParamsStruct>,
    ) -> io::Result<Vec<String>> {
        let mut stmts = vec!["let mut sz = 0;".to_string()];

        for f in fields {
            if let Field::Field {
                name,
                need_compute_offset: true,
                ..
            }
            | Field::List {
                name,
                need_compute_offset: true,
                ..
            }
            | Field::Switch {
                name,
                need_compute_offset: true,
                ..
            } = f
            {
                let fname = format!("compute_{}_offset", name);
                self.emit_compute_func(out, &fname, params_struct, &stmts)?;
            }
            self.field_compute_len_stmts(f, &mut stmts, &Expr::Value(0));
        }

        Ok(stmts)
    }

    pub(super) fn emit_struct_accessors<O: Write>(
        &self,
        out: &mut O,
        struct_rs_typ: &str,
        fields: &[Field],
    ) -> io::Result<()> {
        for f in fields {
            writeln!(out)?;
            if self.handle_client_message_data(out, struct_rs_typ, f)? {
                continue;
            }
            if self.handle_randr_notify_data(out, struct_rs_typ, f)? {
                continue;
            }
            match f {
                Field::Field {
                    name,
                    rs_typ,
                    wire_off,
                    doc,
                    ..
                } if rs_typ == "bool" => {
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "    pub fn {}(&self) -> bool {{", name)?;
                    writeln!(
                        out,
                        "        let val = unsafe {{ *(self.wire_ptr().add({})) }};",
                        self.build_rs_expr(wire_off, "self.", "()", fields)
                    )?;
                    writeln!(out, "        val != 0")?;
                    writeln!(out, "    }}")?;
                }
                Field::Field {
                    name,
                    module,
                    rs_typ,
                    wire_off,
                    r#enum,
                    mask,
                    doc,
                    ..
                } if r#enum.is_some() || mask.is_some() => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    let ret_q_rs_typ = r#enum.as_ref().or_else(|| mask.as_ref()).unwrap();
                    let ret_q_rs_typ = {
                        let (module, rs_typ) = ret_q_rs_typ;
                        (module, rs_typ).qualified_rs_typ()
                    };
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "    pub fn {}(&self) -> {} {{", name, ret_q_rs_typ)?;
                    writeln!(out, "        unsafe {{")?;
                    writeln!(
                        out,
                        "            let offset = {};",
                        self.build_rs_expr(wire_off, "self.", "()", fields)
                    )?;
                    writeln!(
                        out,
                        "            let ptr = self.wire_ptr().add(offset) as *const {};",
                        q_rs_typ
                    )?;
                    writeln!(out, "            let val = *ptr as u32;")?;
                    writeln!(
                        out,
                        "            std::mem::transmute::<u32, {}>(val)",
                        ret_q_rs_typ,
                    )?;
                    writeln!(out, "        }}")?;
                    writeln!(out, "    }}")?;
                }
                Field::Field {
                    name,
                    module,
                    rs_typ,
                    wire_off,
                    is_xid: true,
                    is_union: true,
                    doc,
                    ..
                } => {
                    // XID unions constructed out of context require a `Unknown` variant
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "    fn {}(&self) -> {} {{", name, q_rs_typ)?;
                    writeln!(out, "        unsafe {{")?;
                    writeln!(
                        out,
                        "{}let offset = {};",
                        cg::ind(3),
                        self.build_rs_expr(wire_off, "self.", "()", fields)
                    )?;
                    writeln!(
                        out,
                        "{}let res_id = *(self.wire_ptr().add(offset) as *const u32);",
                        cg::ind(3)
                    )?;
                    writeln!(out, "{}{}::Unknown(res_id)", cg::ind(3), q_rs_typ)?;
                    writeln!(out, "        }}")?;
                    writeln!(out, "    }}")?;
                }
                Field::Field {
                    name,
                    module,
                    rs_typ,
                    wire_off,
                    is_fieldref,
                    is_copy: true,
                    doc,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    // lenfield visibility is not necessary, lists are exposed as sliced
                    let visibility = if *is_fieldref { "" } else { "pub " };
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(
                        out,
                        "{}{}fn {}(&self) -> {} {{",
                        cg::ind(1),
                        visibility,
                        name,
                        q_rs_typ
                    )?;
                    writeln!(out, "{}unsafe {{", cg::ind(2))?;
                    writeln!(
                        out,
                        "{}let offset = {};",
                        cg::ind(3),
                        self.build_rs_expr(wire_off, "self.", "()", fields)
                    )?;
                    writeln!(
                        out,
                        "{}let ptr = self.wire_ptr().add(offset) as *const {};",
                        cg::ind(3),
                        q_rs_typ
                    )?;
                    writeln!(out, "            *ptr")?;
                    writeln!(out, "        }}")?;
                    writeln!(out, "    }}")?;
                }
                Field::Field {
                    name,
                    module,
                    rs_typ,
                    wire_off,
                    wire_sz,
                    is_copy: false,
                    is_union: false,
                    struct_style,
                    params_struct,
                    doc,
                    need_compute_offset,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();

                    let params_expr = self.build_params_expr(
                        params_struct.as_ref(),
                        module.as_ref().map(|s| s.as_str()),
                        "self.",
                        "()",
                    );
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "    pub fn {}(&self) -> &{} {{", name, q_rs_typ)?;
                    writeln!(out, "{}unsafe {{", cg::ind(2))?;
                    if *need_compute_offset {
                        writeln!(
                            out,
                            "{}let offset = Self::compute_{}_offset(self.wire_ptr(), {});",
                            cg::ind(3),
                            name,
                            params_expr
                        )?;
                    } else {
                        writeln!(
                            out,
                            "{}let offset = {};",
                            cg::ind(3),
                            self.build_rs_expr(wire_off, "self.", "()", fields)
                        )?;
                    }
                    if let Some(StructStyle::DynBuf) = struct_style {
                        writeln!(
                            out,
                            "{}let len = {}::compute_wire_len(self.wire_ptr().add(offset), {});",
                            cg::ind(3),
                            q_rs_typ,
                            params_expr
                        )?;
                    } else {
                        writeln!(
                            out,
                            "            let len = {};",
                            self.build_rs_expr(wire_sz, "self.", "()", fields)
                        )?;
                    }
                    writeln!(out, "            let data = std::slice::from_raw_parts(self.wire_ptr().add(offset), len);")?;
                    writeln!(out, "            {}::from_data(data)", q_rs_typ,)?;
                    writeln!(out, "        }}")?;
                    writeln!(out, "    }}")?;
                }
                Field::Field {
                    name,
                    module,
                    rs_typ,
                    wire_off,
                    wire_sz,
                    is_copy: false,
                    is_union: true,
                    need_compute_offset,
                    doc,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "    fn {}(&self) -> {} {{", name, q_rs_typ)?;
                    writeln!(out, "        unsafe {{")?;
                    if *need_compute_offset {
                        writeln!(
                            out,
                            "            let offset = Self::compute_{}_offset(self.wire_ptr());",
                            name
                        )?;
                    } else {
                        writeln!(
                            out,
                            "            let offset = {};",
                            self.build_rs_expr(wire_off, "self.", "()", fields)
                        )?;
                    }
                    writeln!(
                        out,
                        "{}let len = {};",
                        cg::ind(3),
                        self.build_rs_expr(wire_sz, "self.", "()", fields)
                    )?;
                    writeln!(out, "{}let data = std::slice::from_raw_parts(self.wire_ptr().add(offset), len);", cg::ind(3))?;
                    writeln!(out, "{}{}::from_data(data)", cg::ind(3), q_rs_typ)?;
                    writeln!(out, "        }}")?;
                    writeln!(out, "    }}")?;
                }
                Field::List {
                    name,
                    wire_off,
                    len_expr,
                    is_prop: true,
                    doc,
                    ..
                } => {
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(
                        out,
                        "{}pub fn {}<P: PropEl>(&self) -> &[P] {{",
                        cg::ind(1),
                        name
                    )?;
                    writeln!(
                        out,
                        "{}assert_eq!(self.format(), P::FORMAT, \"mismatched format of {}::{}::{}\");",
                        cg::ind(2),
                        self.xcb_mod,
                        struct_rs_typ,
                        name
                    )?;
                    writeln!(out, "{}unsafe {{", cg::ind(2))?;
                    writeln!(
                        out,
                        "{}let offset = {};",
                        cg::ind(3),
                        self.build_rs_expr(wire_off, "self.", "()", fields)
                    )?;
                    writeln!(
                        out,
                        "{}let len = {};",
                        cg::ind(3),
                        self.build_rs_expr(len_expr, "self.", "()", fields)
                    )?;
                    writeln!(
                        out,
                        "{}let len = len / std::mem::size_of::<P>();",
                        cg::ind(3)
                    )?;
                    writeln!(
                        out,
                        "{}let ptr = self.wire_ptr().add(offset) as *const P;",
                        cg::ind(3),
                    )?;
                    writeln!(out, "{}std::slice::from_raw_parts(ptr, len)", cg::ind(3))?;
                    writeln!(out, "{}}}", cg::ind(2))?;
                    writeln!(out, "{}}}", cg::ind(1))?;
                }
                Field::List {
                    name,
                    module,
                    rs_typ,
                    wire_off,
                    len_expr,
                    struct_style: None,
                    doc,
                    ..
                } if rs_typ != "char" && !matches!(len_expr, Expr::Value(_)) => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    let params = len_expr.params_str();
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(
                        out,
                        "    pub fn {}(&self{}) -> &[{}] {{",
                        name, params, q_rs_typ
                    )?;
                    writeln!(out, "{}unsafe {{", cg::ind(2))?;
                    writeln!(
                        out,
                        "{}let offset = {};",
                        cg::ind(3),
                        self.build_rs_expr(wire_off, "self.", "()", fields)
                    )?;
                    writeln!(
                        out,
                        "{}let len = {};",
                        cg::ind(3),
                        self.build_rs_expr(len_expr, "self.", "()", fields)
                    )?;
                    writeln!(
                        out,
                        "{}let ptr = self.wire_ptr().add(offset) as *const {};",
                        cg::ind(3),
                        q_rs_typ
                    )?;
                    writeln!(out, "{}std::slice::from_raw_parts(ptr, len)", cg::ind(3))?;
                    writeln!(out, "{}}}", cg::ind(2))?;
                    writeln!(out, "{}}}", cg::ind(1))?;
                }
                Field::List {
                    name,
                    module,
                    rs_typ,
                    wire_off,
                    len_expr,
                    struct_style: None,
                    doc,
                    ..
                } if rs_typ != "char" => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    let len = len_expr.fixed_length().unwrap();
                    let params = len_expr.params_str();
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(
                        out,
                        "    pub fn {}(&self{}) -> &[{}; {}] {{",
                        name, params, q_rs_typ, len
                    )?;

                    writeln!(out, "        unsafe {{")?;
                    writeln!(
                        out,
                        "            let offset = {};",
                        self.build_rs_expr(wire_off, "self.", "()", fields)
                    )?;
                    writeln!(
                        out,
                        "            let ptr = self.wire_ptr().add(offset) as *const [{}; {}];",
                        q_rs_typ, len
                    )?;
                    writeln!(out, "            &*ptr")?;
                    writeln!(out, "        }}")?;
                    writeln!(out, "    }}")?;
                }
                Field::List {
                    name,
                    rs_typ,
                    wire_off,
                    len_expr,
                    doc,
                    ..
                } if rs_typ == "char" => {
                    let params = len_expr.params_str();
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(out, "    pub fn {}(&self{}) -> &str {{", name, params)?;

                    writeln!(out, "        unsafe {{")?;
                    writeln!(
                        out,
                        "            let offset = {};",
                        self.build_rs_expr(wire_off, "self.", "()", fields)
                    )?;
                    writeln!(
                        out,
                        "            let len = {} as _;",
                        self.build_rs_expr(len_expr, "self.", "()", fields)
                    )?;
                    writeln!(out, "            let ptr = self.wire_ptr().add(offset);",)?;
                    writeln!(
                        out,
                        "            let utf8 = std::slice::from_raw_parts(ptr, len);",
                    )?;
                    writeln!(out, "            std::str::from_utf8(utf8).unwrap()")?;
                    writeln!(out, "        }}")?;
                    writeln!(out, "    }}")?;
                }
                Field::List {
                    name,
                    module,
                    rs_typ,
                    wire_off,
                    len_expr: Expr::UntilEnd,
                    struct_style: None | Some(StructStyle::WireLayout | StructStyle::FixBuf),
                    doc,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();

                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(
                        out,
                        "{}pub fn {}(&self) -> &[{}] {{",
                        cg::ind(1),
                        name,
                        q_rs_typ
                    )?;
                    writeln!(out, "{}unsafe {{", cg::ind(2))?;
                    writeln!(
                        out,
                        "{}let offset = {};",
                        cg::ind(3),
                        self.build_rs_expr(wire_off, "self.", "()", fields)
                    )?;
                    writeln!(out, "{}assert_eq!((self.length() as usize - offset) % std::mem::size_of::<{}>(), 0);", cg::ind(3), q_rs_typ)?;
                    writeln!(out, "{}let len = (self.length() as usize - offset) / std::mem::size_of::<{}>();", cg::ind(3), q_rs_typ)?;
                    writeln!(out, "{}std::slice::from_raw_parts(self.wire_ptr().add(offset) as *const {}, len)", cg::ind(3), q_rs_typ)?;
                    writeln!(out, "{}}}", cg::ind(2))?;
                    writeln!(out, "{}}}", cg::ind(1))?;
                }
                Field::List {
                    name,
                    module,
                    rs_typ,
                    wire_off,
                    len_expr,
                    struct_style: Some(StructStyle::WireLayout | StructStyle::FixBuf),
                    doc,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    let params = len_expr.params_str();
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(
                        out,
                        "    pub fn {}(&self{}) -> &[{}] {{",
                        name, params, q_rs_typ
                    )?;

                    writeln!(out, "        unsafe {{")?;
                    writeln!(
                        out,
                        "            let offset = {};",
                        self.build_rs_expr(wire_off, "self.", "()", fields)
                    )?;
                    writeln!(
                        out,
                        "            let len = {} as _;",
                        self.build_rs_expr(len_expr, "self.", "()", fields)
                    )?;
                    writeln!(
                        out,
                        "            let ptr = self.wire_ptr().add(offset) as *const {};",
                        q_rs_typ
                    )?;
                    writeln!(out, "            std::slice::from_raw_parts(ptr, len)",)?;
                    writeln!(out, "        }}")?;
                    writeln!(out, "    }}")?;
                }
                Field::List {
                    name,
                    module,
                    rs_typ,
                    wire_off,
                    len_expr,
                    struct_style: Some(StructStyle::DynBuf),
                    params_struct,
                    need_compute_offset,
                    doc,
                    ..
                } => {
                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                    let params = len_expr.params_str();
                    let params_expr = self.build_params_expr(
                        params_struct.as_ref(),
                        module.as_ref().map(|s| s.as_str()),
                        "self.",
                        "()",
                    );
                    if let Some(doc) = doc {
                        doc.emit(out, 1)?;
                    }
                    writeln!(
                        out,
                        "    pub fn {}(&self{}) -> {}Iterator {{",
                        name, params, q_rs_typ
                    )?;
                    writeln!(out, "        unsafe {{")?;
                    if *need_compute_offset {
                        writeln!(
                            out,
                            "{}let offset = Self::compute_{}_offset(self.wire_ptr(), {});",
                            cg::ind(3),
                            name,
                            params_expr
                        )?;
                    } else {
                        writeln!(
                            out,
                            "{}let offset = {};",
                            cg::ind(3),
                            self.build_rs_expr(wire_off, "self.", "()", fields)
                        )?;
                    }
                    writeln!(out, "{}{}Iterator {{", cg::ind(3), q_rs_typ)?;
                    writeln!(out, "{}    params: {},", cg::ind(3), params_expr)?;
                    writeln!(
                        out,
                        "{}    rem: {},",
                        cg::ind(3),
                        self.build_rs_expr(len_expr, "self.", "()", fields)
                    )?;
                    writeln!(out, "{}    ptr: self.wire_ptr().add(offset),", cg::ind(3))?;
                    writeln!(out, "{}    phantom: std::marker::PhantomData,", cg::ind(3))?;
                    writeln!(out, "{}}}", cg::ind(3))?;
                    writeln!(out, "        }}")?;
                    writeln!(out, "    }}")?;
                }
                _ => {}
            }
        }
        Ok(())
    }

    // specific handling of ClientMessageEvent::data()
    // This is nearly static function definition. We could possibly directly define that in the
    // xproto module in lib.rs
    fn handle_client_message_data<O: Write>(
        &self,
        out: &mut O,
        struct_rs_typ: &str,
        field: &Field,
    ) -> io::Result<bool> {
        if self.xcb_mod == "xproto"
            && struct_rs_typ == "ClientMessageEvent"
            && matches!(field, Field::Field{name, ..} if name == "data")
        {
            writeln!(out)?;
            writeln!(
                out,
                "{}pub fn data(&self) -> ClientMessageData {{",
                cg::ind(1)
            )?;
            writeln!(out, "{}unsafe {{", cg::ind(2))?;
            writeln!(out, "{}match self.format() {{", cg::ind(3))?;
            for sz in [8, 16, 32] {
                writeln!(
                    out,
                    "{}{} => ClientMessageData::Data{} (",
                    cg::ind(4),
                    sz,
                    sz
                )?;
                writeln!(out, "{}std::slice::from_raw_parts(", cg::ind(5))?;
                writeln!(
                    out,
                    "{}self.wire_ptr().add(12) as *const u{}, {}",
                    cg::ind(6),
                    sz,
                    (20 * 8) / sz
                )?;
                writeln!(out, "{}).try_into().unwrap()", cg::ind(5))?;
                writeln!(out, "{}),", cg::ind(4))?;
            }
            writeln!(
                out,
                "{}format => unreachable!(\"invalid ClientMessageEvent format: {{}}\", format),",
                cg::ind(4)
            )?;
            writeln!(out, "{}}}", cg::ind(3))?;
            writeln!(out, "{}}}", cg::ind(2))?;
            writeln!(out, "{}}}", cg::ind(1))?;
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn handle_randr_notify_data<O: Write>(
        &self,
        out: &mut O,
        struct_rs_typ: &str,
        field: &Field,
    ) -> io::Result<bool> {
        if self.xcb_mod == "randr"
            && struct_rs_typ == "NotifyEvent"
            && matches!(field, Field::Field{name, ..} if name == "u")
        {
            writeln!(out)?;
            writeln!(out, "{}pub fn u(&self) -> NotifyData {{", cg::ind(1))?;
            writeln!(out, "{}unsafe {{", cg::ind(2))?;
            writeln!(out, "{}match self.sub_code() {{", cg::ind(3))?;

            for code in RANDR_SUBCODES {
                writeln!(
                    out,
                    "{}Notify::{} => NotifyData::{}(",
                    cg::ind(4),
                    code.0,
                    code.2
                )?;
                writeln!(out, "{}*{}::from_data(", cg::ind(5), code.1)?;
                writeln!(
                    out,
                    "{}std::slice::from_raw_parts(self.wire_ptr().add(4), 28)",
                    cg::ind(6)
                )?;
                writeln!(out, "{})", cg::ind(5))?;
                writeln!(out, "{}),", cg::ind(4))?;
            }

            writeln!(out, "{}}}", cg::ind(3))?;
            writeln!(out, "{}}}", cg::ind(2))?;
            writeln!(out, "{}}}", cg::ind(1))?;

            Ok(true)
        } else {
            Ok(false)
        }
    }

    pub(super) fn emit_debug_impl<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        fields: &[Field],
    ) -> io::Result<()> {
        writeln!(out)?;
        writeln!(out, "impl std::fmt::Debug for {} {{", rs_typ)?;
        writeln!(
            out,
            "    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {{"
        )?;
        writeln!(out, "        f.debug_struct(\"{}\")", rs_typ)?;
        for f in fields {
            match f {
                Field::Field { name, .. } => {
                    writeln!(out, "{}.field(\"{}\", &self.{}())", cg::ind(3), name, name)?;
                }
                Field::List {
                    name,
                    is_prop: true,
                    ..
                } => {
                    writeln!(
                        out,
                        "{}.field(\"{}\", &self.{}::<u8>())",
                        cg::ind(3),
                        name,
                        name
                    )?;
                }
                Field::List { name, wire_sz, .. } if wire_sz.params().is_empty() => {
                    writeln!(out, "{}.field(\"{}\", &self.{}())", cg::ind(3), name, name)?;
                }
                Field::List { .. } => {
                    // TODO
                }
                Field::Switch { .. } => {
                    // TODO
                }
                Field::Pad {
                    wire_sz: Expr::Value(sz),
                    ..
                } => {
                    writeln!(out, "{}.field(\"pad\", &{})", cg::ind(3), sz)?;
                }
                Field::AlignPad {
                    wire_sz: Expr::AlignPad(sz, _),
                    ..
                } => {
                    writeln!(out, "{}.field(\"align_pad\", &{})", cg::ind(3), sz)?;
                }
                _ => {}
            }
        }
        writeln!(out, "            .finish()")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        Ok(())
    }

    fn emit_dyn_buf_struct_iterator<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        params_struct: Option<&ParamsStruct>,
    ) -> io::Result<()> {
        writeln!(out)?;
        writeln!(out, "#[derive(Clone)]")?;
        writeln!(out, "pub struct {}Iterator<'a> {{", rs_typ)?;
        writeln!(out, "    pub(crate) params: {},", params_struct.rs_typ())?;
        writeln!(out, "    pub(crate) rem: usize,")?;
        writeln!(out, "    pub(crate) ptr: *const u8,")?;
        writeln!(
            out,
            "    pub(crate) phantom: std::marker::PhantomData<&'a {}>,",
            rs_typ
        )?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "impl<'a> Iterator for {}Iterator<'a> {{", rs_typ)?;
        writeln!(out, "    type Item = &'a {};", rs_typ)?;
        writeln!(out)?;
        writeln!(
            out,
            "    fn next(&mut self) -> std::option::Option<Self::Item> {{"
        )?;
        writeln!(out, "        if self.rem == 0 {{")?;
        writeln!(out, "            None")?;
        writeln!(out, "        }} else {{ unsafe {{")?;
        writeln!(out, "            self.rem -= 1;")?;
        writeln!(
            out,
            "            let len = {}::compute_wire_len(self.ptr, self.params);",
            rs_typ
        )?;
        writeln!(
            out,
            "            let res = {}::from_data(std::slice::from_raw_parts(self.ptr, len));",
            rs_typ
        )?;
        writeln!(out, "            self.ptr = self.ptr.add(len);")?;
        writeln!(out, "            Some(res)")?;
        writeln!(out, "        }}}}")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(
            out,
            "impl<'a> std::fmt::Debug for {}Iterator<'a> {{",
            rs_typ
        )?;
        writeln!(
            out,
            "    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {{"
        )?;
        writeln!(out, "        f.debug_list().entries(self.clone()).finish()")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;
        Ok(())
    }
}

struct FieldInfo {
    name: String,
    module: Option<String>,
    typ: String,
    rs_typ: String,
    wire_sz: Expr,
    has_wire_layout: bool,
    struct_style: Option<StructStyle>,
    params_struct: Option<ParamsStruct>,
    doc: Option<DocField>,
    is_union: bool,
    is_xid: bool,
    is_mask: bool,
}

pub(super) const RANDR_SUBCODES: &[(&str, &str, &str)] = &[
    ("CrtcChange", "CrtcChange", "Cc"),
    ("OutputChange", "OutputChange", "Oc"),
    ("OutputProperty", "OutputProperty", "Op"),
    ("ProviderChange", "ProviderChange", "Pc"),
    ("ProviderProperty", "ProviderProperty", "Pp"),
    ("ResourceChange", "ResourceChange", "Rc"),
    ("Lease", "LeaseNotify", "Lc"),
];

pub(super) fn enum_mask_qualified_rs_typ(
    module: &Option<String>,
    rs_typ: &str,
    r#enum: &Option<(Option<String>, String)>,
    mask: &Option<(Option<String>, String)>,
) -> String {
    let mod_rs_typ = r#enum
        .as_ref()
        .or_else(|| mask.as_ref())
        .map(|(m, t)| (m.as_ref().map(|m| m.as_str()), t.as_str()))
        .or_else(|| Some((module.as_ref().map(|m| m.as_str()), rs_typ)))
        .unwrap();
    mod_rs_typ.qualified_rs_typ()
}

pub(super) fn make_field(name: String, typ: String) -> ir::Field {
    ir::Field::Field {
        name,
        typ,
        r#enum: None,
        mask: None,
        altenum: None,
        altmask: None,
    }
}

use super::r#enum::{self};
use super::r#struct::{ParamsStruct, ResolvedFields};
use super::{CodeGen, Expr, Field, SwitchCase, TypeInfo};
use crate::cg::{self, util, QualifiedRsTyp, StructStyle};
use crate::ir;

use std::io::{self, Write};

impl CodeGen {
    #[allow(clippy::too_many_arguments)]
    pub(super) fn resolve_switch(
        &mut self,
        parent_rs_typ: &str,
        parent_switch: &str,
        name: &str,
        expr: &Expr,
        wire_off: &Expr,
        cases: &[ir::SwitchCase],
        prev_fields: &mut [Field],
        need_compute_offset: bool,
    ) -> Field {
        // switch types are made-up, so we create the typ (same as intended rs_typ)
        let typ = parent_rs_typ.to_string() + &util::tit_cap(name);
        let mut switch_rs_typ = typ.clone();

        let mut module = None;

        let mut emit = true;
        for ex in &self.switch_exceptions {
            if ex.module == self.xcb_mod && ex.rs_typ == switch_rs_typ {
                switch_rs_typ = ex.new_rs_typ.to_string();
                module = ex.new_module.map(str::to_owned);
                emit = ex.emit;
                break;
            }
        }

        let is_mask = {
            let check1 = cases.iter().all(|sc| sc.bit);
            let check2 = cases.iter().any(|sc| sc.bit);
            assert_eq!(check1, check2, "switch cannot mix case and bitcase");
            check1
        };

        let name = util::to_snake_case(name);

        let switch_name = if parent_switch.is_empty() {
            name.clone()
        } else {
            format!("{}_{}", parent_switch, name)
        };

        let mut param_fields = Vec::new();

        let cases: Vec<SwitchCase> = cases
            .iter()
            .map(|sc| {
                let ir::SwitchCase {
                    name,
                    fields,
                    exprs,
                    ..
                } = sc;
                let name = name
                    .as_ref()
                    .map(|n| cg::rust_type_name(n))
                    .unwrap_or_else(|| match &exprs[0] {
                        ir::Expr::EnumRef { item, .. } => r#enum::map_enum_item_name(item),
                        _ => unreachable!("switch expressions not enum ref"),
                    });

                let exprs = exprs
                    .iter()
                    .map(|e| self.resolve_expr(e))
                    .collect::<Vec<_>>();
                let ResolvedFields {
                    fields,
                    unresolved_fieldrefs: mut uf,
                    ..
                } = self.resolv_struct_fields(&switch_rs_typ, &switch_name, fields, None);
                param_fields.append(&mut uf);
                SwitchCase {
                    name,
                    fields,
                    exprs,
                }
            })
            .collect();

        let expr_fields = expr.fieldrefs();
        assert!(
            !expr_fields.is_empty(),
            "switch {}::{} has no fieldref expr: {:?}",
            parent_rs_typ,
            name,
            expr,
        );

        let maskenum = {
            let (r#enum, mask) = prev_fields
                .iter()
                .find_map(|f| match f {
                    Field::Field {
                        name, r#enum, mask, ..
                    } if name == expr_fields[0] => Some((r#enum, mask)),
                    _ => None,
                })
                .unwrap_or_else(|| {
                    panic!(
                        "cannot find field {} for switch {}::{}",
                        expr_fields[0], parent_rs_typ, name
                    )
                });

            assert!(r#enum.is_some() && !is_mask || mask.is_some() && is_mask);

            let maskenum = r#enum.as_ref().unwrap_or_else(|| mask.as_ref().unwrap());
            maskenum.clone()
        };

        // {
        //     let enumtyp = self.typinfos.get_mut(&maskenum.1);
        //     if let Some(TypeInfo::Bitflags { ref mut rs_typ, .. }) = enumtyp {
        //         switch_rs_typ = rs_typ.clone() + "Mask";
        //         mem::swap(&mut switch_rs_typ, rs_typ);
        //     }
        // }

        param_fields.sort();
        param_fields.dedup();

        let params = expr_fields
            .into_iter()
            .map(str::to_owned)
            .chain(param_fields.into_iter())
            .collect();

        let params_struct = ParamsStruct {
            rs_typ: switch_rs_typ.clone() + "Params",
            params,
        };

        let typinfo = TypeInfo::Switch {
            module: module.clone(),
            rs_typ: switch_rs_typ.clone(),
            wire_sz: Expr::Unknown("switch len".into()), // FIXME switch size expr (may be a method?)
            maskenum,
            params_struct: params_struct.clone(),
            expr: expr.clone(),
            cases,
            is_mask,
            emit,
        };
        let field = Field::Switch {
            name,
            module,
            rs_typ: switch_rs_typ,
            wire_sz: Expr::Unknown("switch len".to_string()),
            wire_off: wire_off.clone(),
            params_struct,
            expr: expr.clone(),
            is_mask,
            need_compute_offset,
            doc: None,
        };

        self.register_typ(typ, typinfo);

        field
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn emit_switch<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        expr: &Expr,
        cases: &[SwitchCase],
        maskenum: &(Option<String>, String),
        params_struct: &ParamsStruct,
        is_mask: bool,
    ) -> io::Result<()> {
        params_struct.emit(out)?;

        writeln!(out)?;
        writeln!(out, "#[derive(Clone, Debug)]")?;
        writeln!(out, "pub enum {} {{", rs_typ)?;
        for c in cases {
            assert!(!c.fields.is_empty());

            if c.fields.len() == 1 {
                match &c.fields[0] {
                    Field::Field { module, rs_typ, .. } => {
                        let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                        writeln!(out, "    {}({}),", c.name, q_rs_typ)?;
                    }
                    Field::List { rs_typ, .. } if rs_typ == "char" => {
                        writeln!(out, "    {}(String),", c.name)?;
                    }
                    Field::List {
                        module,
                        rs_typ,
                        struct_style,
                        ..
                    } => {
                        let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                        let buf = if matches!(struct_style, Some(StructStyle::DynBuf)) {
                            "Buf"
                        } else {
                            ""
                        };
                        writeln!(out, "    {}(Vec<{}{}>),", c.name, q_rs_typ, buf)?;
                    }
                    _ => unreachable!(),
                };
            } else {
                writeln!(out, "    {}{{", c.name)?;
                for f in &c.fields {
                    match f {
                        Field::Field {
                            module,
                            name,
                            rs_typ,
                            struct_style,
                            ..
                        } => {
                            let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                            let buf = if matches!(struct_style, Some(StructStyle::DynBuf)) {
                                "Buf"
                            } else {
                                ""
                            };
                            writeln!(out, "        {}: {}{},", name, q_rs_typ, buf)?;
                        }
                        Field::List { name, rs_typ, .. } if rs_typ == "char" => {
                            writeln!(out, "        {}: String,", name)?;
                        }
                        Field::List {
                            module,
                            name,
                            rs_typ,
                            ..
                        } => {
                            let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                            writeln!(out, "        {}: Vec<{}>,", name, q_rs_typ)?;
                        }
                        Field::Switch {
                            name,
                            rs_typ,
                            is_mask: true,
                            ..
                        } => {
                            writeln!(out, "        {}: Vec<{}>,", name, rs_typ)?;
                        }
                        Field::Pad { .. } => {}
                        Field::AlignPad { .. } => {}
                        _ => unreachable!("{:#?}", f),
                    }
                }
                writeln!(out, "    }},")?;
            }
        }
        writeln!(out, "}}")?;

        if is_mask {
            self.emit_mask_switch_impl(out, rs_typ, maskenum, cases)?;
        } else {
            self.emit_enum_switch_impl(out, rs_typ, maskenum, cases)?;
        }

        writeln!(out)?;
        if is_mask {
            writeln!(out, "impl base::Wired for &[{}] {{", rs_typ)?;
        } else {
            writeln!(out, "impl base::Wired for {} {{", rs_typ)?;
        }
        writeln!(out, "    type Params = {};", params_struct.rs_typ)?;
        self.emit_switch_compute_wire_len(out, expr, rs_typ, cases, params_struct, is_mask)?;
        self.emit_switch_wire_len(out, rs_typ, cases, is_mask)?;
        self.emit_switch_serialize(out, rs_typ, cases, is_mask)?;
        writeln!(out, "}}")?;
        Ok(())
    }

    pub(super) fn emit_switch_compute_wire_len<O: Write>(
        &self,
        out: &mut O,
        expr: &Expr,
        rs_typ: &str,
        cases: &[SwitchCase],
        params_struct: &ParamsStruct,
        is_mask: bool,
    ) -> io::Result<()> {
        writeln!(out)?;
        writeln!(
            out,
            "    unsafe fn compute_wire_len(ptr: *const u8, params: Self::Params) -> usize {{"
        )?;
        writeln!(out, "{}let {} {{", cg::ind(2), params_struct.rs_typ)?;
        for p in &params_struct.params {
            writeln!(out, "{}{},", cg::ind(3), p)?;
        }
        writeln!(out, "{}}} = params;", cg::ind(2))?;

        writeln!(
            out,
            "{}let expr = {};",
            cg::ind(2),
            self.build_rs_expr(expr, "", "", &[])
        )?;

        if is_mask {
            writeln!(out, "{}let mut sz = 0usize;", cg::ind(2))?;
        }

        for c in cases {
            let exprs: Vec<String> = c
                .exprs
                .iter()
                .map(|e| self.build_rs_expr(e, "", "", &[]))
                .collect();
            let exprs = exprs.join(if is_mask { " | " } else { " || " });
            if is_mask {
                writeln!(out, "        if expr & {} != 0 {{", exprs)?;
            } else {
                writeln!(out, "        if expr == {} {{", exprs)?;
                writeln!(out, "            let mut sz = 0usize;")?;
            }
            for cf in &c.fields {
                let mut stmts = Vec::new();
                self.field_compute_len_stmts(cf, &mut stmts, &Expr::Value(0));
                for s in stmts {
                    writeln!(out, "            {}", s)?;
                }
            }
            if !is_mask {
                writeln!(out, "            return sz;")?;
            }
            writeln!(out, "        }}")?;
        }

        if is_mask {
            writeln!(out, "{}sz", cg::ind(2))?;
        } else {
            writeln!(
                out,
                "        unreachable!(\"could not match switch expression in {}::{}::compute_wire_len\")",
                self.xcb_mod, rs_typ
            )?;
        }
        writeln!(out, "    }}")?;
        Ok(())
    }

    fn _emit_switch_wire_len<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        cases: &[SwitchCase],
        is_mask: bool,
    ) -> io::Result<()> {
        writeln!(out)?;
        writeln!(out, "{}fn wire_len(&self) -> usize {{", cg::ind(1))?;
        writeln!(out, "{}let mut sz = 0usize;", cg::ind(2))?;
        let ind = if is_mask {
            writeln!(out, "{}for el in self.iter() {{", cg::ind(2))?;
            writeln!(out, "{}match el {{", cg::ind(3))?;
            3
        } else {
            writeln!(out, "{}match self {{", cg::ind(2))?;
            2
        };
        for sc in cases {
            let (open, close) = if sc.fields.len() == 1 {
                ("(", ")")
            } else {
                ("{", "}")
            };

            writeln!(out, "{}{}::{}{}", cg::ind(ind + 1), rs_typ, sc.name, open)?;

            let mut unmatched = false;
            for f in &sc.fields {
                match f {
                    Field::Field { name, .. } => writeln!(out, "{}{},", cg::ind(ind + 2), name)?,
                    Field::List { name, .. } => writeln!(out, "{}{},", cg::ind(ind + 2), name)?,
                    Field::Switch { name, .. } => writeln!(out, "{}{},", cg::ind(ind + 2), name)?,
                    _ => unmatched = true,
                }
            }
            if unmatched {
                writeln!(out, "{}..", cg::ind(ind + 2))?;
            }

            writeln!(out, "{}{} => {{", cg::ind(ind + 1), close)?;

            for f in &sc.fields {
                match f {
                    Field::Field {
                        name,
                        struct_style: Some(StructStyle::DynBuf),
                        ..
                    } => {
                        writeln!(out, "{}sz += {}.wire_len();", cg::ind(ind + 2), name)?;
                    }
                    Field::Field { wire_sz, .. } => {
                        writeln!(
                            out,
                            "{}sz += {};",
                            cg::ind(ind + 2),
                            self.build_rs_expr(wire_sz, "", "", &[])
                        )?;
                    }
                    Field::List {
                        name,
                        struct_style: Some(StructStyle::DynBuf),
                        ..
                    } => {
                        writeln!(
                            out,
                            "{}sz += {}.iter().map(|item| item.wire_len()).sum::<usize>();",
                            cg::ind(ind + 2),
                            name,
                        )?;
                    }
                    Field::List {
                        name,
                        module,
                        rs_typ,
                        ..
                    } => {
                        let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                        writeln!(
                            out,
                            "{}sz += {}.len() * std::mem::size_of::<{}>();",
                            cg::ind(ind + 2),
                            name,
                            q_rs_typ
                        )?;
                    }
                    Field::Switch { name, .. } => {
                        writeln!(
                            out,
                            "{}sz += {}.as_slice().wire_len();",
                            cg::ind(ind + 2),
                            name
                        )?;
                    }
                    Field::Pad {
                        wire_sz: Expr::Value(sz),
                        ..
                    } => {
                        writeln!(out, "{}sz += {};", cg::ind(ind + 2), sz)?;
                    }
                    Field::AlignPad {
                        wire_sz: Expr::AlignPad(sz, _),
                        ..
                    } => {
                        writeln!(
                            out,
                            "{}sz += base::align_pad(sz, {});",
                            cg::ind(ind + 2),
                            sz
                        )?;
                    }
                    _ => unreachable!("{:#?}", f),
                }
            }
            writeln!(out, "{}}}", cg::ind(ind + 1))?;
        }
        if is_mask {
            writeln!(out, "{}}}", cg::ind(3))?;
        }
        writeln!(out, "{}}}", cg::ind(2))?;
        writeln!(out, "{}sz", cg::ind(2))?;
        writeln!(out, "{}}}", cg::ind(1))?;
        Ok(())
    }

    fn emit_switch_wire_len<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        cases: &[SwitchCase],
        is_mask: bool,
    ) -> io::Result<()> {
        writeln!(out)?;
        writeln!(out, "    fn wire_len(&self) -> usize {{")?;
        writeln!(out, "{}let mut sz = 0usize;", cg::ind(2))?;
        let ind = if is_mask {
            writeln!(out, "{}for el in self.iter() {{", cg::ind(2))?;
            writeln!(out, "{}match el {{", cg::ind(3))?;
            3
        } else {
            writeln!(out, "{}match self {{", cg::ind(2))?;
            2
        };

        for sc in cases {
            let (open, close) = if sc.fields.len() == 1 {
                ("(", ")")
            } else {
                ("{", "}")
            };

            writeln!(out, "{}{}::{}{}", cg::ind(ind + 1), rs_typ, sc.name, open)?;

            for f in &sc.fields {
                match f {
                    Field::Field { name, .. }
                    | Field::List { name, .. }
                    | Field::Switch { name, .. } => writeln!(out, "{}{},", cg::ind(ind + 2), name)?,
                    Field::Expr { .. } => unreachable!(),
                    Field::Pad { .. } => {}
                    Field::AlignPad { .. } => {}
                }
            }

            writeln!(out, "{}{} => {{", cg::ind(ind + 1), close)?;
            for f in &sc.fields {
                match f {
                    Field::Field {
                        wire_sz: Expr::Value(sz),
                        ..
                    }
                    | Field::List {
                        wire_sz: Expr::Value(sz),
                        ..
                    }
                    | Field::Pad {
                        wire_sz: Expr::Value(sz),
                        ..
                    } => {
                        writeln!(out, "{}sz += {};", cg::ind(ind + 2), sz)?;
                    }
                    Field::Field { name, .. } => {
                        writeln!(out, "{}sz += {}.wire_len();", cg::ind(ind + 2), name)?;
                    }
                    Field::List { name, rs_typ, .. } if rs_typ == "char" => {
                        writeln!(out, "{}sz += {}.len();", cg::ind(ind + 2), name)?;
                    }
                    Field::List { name, .. } => {
                        writeln!(out, "{}for el in {} {{", cg::ind(ind + 2), name)?;
                        writeln!(out, "{}sz += el.wire_len();", cg::ind(ind + 3))?;
                        writeln!(out, "{}}}", cg::ind(ind + 2))?;
                    }
                    Field::Switch { name, is_mask, .. } => {
                        let acc = if *is_mask { ".as_slice()" } else { "" };
                        writeln!(out, "{}sz += {}{}.wire_len();", cg::ind(ind + 2), name, acc)?;
                    }
                    Field::AlignPad {
                        wire_sz: Expr::AlignPad(sz, _),
                        ..
                    } => {
                        writeln!(
                            out,
                            "{}sz += base::align_pad(sz, {});",
                            cg::ind(ind + 2),
                            sz
                        )?;
                    }
                    _ => unreachable!("{:#?}", f),
                }
            }
            writeln!(out, "{}}}", cg::ind(ind + 1))?;
        }

        writeln!(out, "{}}}", cg::ind(ind))?;
        if is_mask {
            writeln!(out, "{}}}", cg::ind(2))?;
        }
        writeln!(out, "{}sz", cg::ind(2))?;
        writeln!(out, "    }}")?;
        Ok(())
    }

    fn emit_switch_serialize<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        cases: &[SwitchCase],
        is_mask: bool,
    ) -> io::Result<()> {
        writeln!(out)?;
        writeln!(
            out,
            "    fn serialize(&self, wire_buf: &mut [u8]) -> usize {{"
        )?;
        writeln!(out, "{}let mut offset = 0usize;", cg::ind(2))?;
        let ind = if is_mask {
            writeln!(out, "{}for el in self.iter() {{", cg::ind(2))?;
            writeln!(out, "{}match el {{", cg::ind(3))?;
            3
        } else {
            writeln!(out, "{}match self {{", cg::ind(2))?;
            2
        };

        for sc in cases {
            let (open, close) = if sc.fields.len() == 1 {
                ("(", ")")
            } else {
                ("{", "}")
            };

            writeln!(out, "{}{}::{}{}", cg::ind(ind + 1), rs_typ, sc.name, open)?;

            for f in &sc.fields {
                match f {
                    Field::Field { name, .. }
                    | Field::List { name, .. }
                    | Field::Switch { name, .. } => writeln!(out, "{}{},", cg::ind(ind + 2), name)?,
                    Field::Expr { .. } => unreachable!(),
                    Field::Pad { .. } => {}
                    Field::AlignPad { .. } => {}
                }
            }

            writeln!(out, "{}{} => {{", cg::ind(ind + 1), close)?;
            for f in &sc.fields {
                match f {
                    Field::Field {
                        name,
                        rs_typ,
                        wire_sz: Expr::Value(sz),
                        ..
                    } if rs_typ == "bool" => {
                        // have to take into account "BOOL32"
                        let typ = if *sz == 4 {
                            "u32"
                        } else if *sz == 1 {
                            "u8"
                        } else {
                            unreachable!("unknown sized bool")
                        };
                        writeln!(
                            out,
                            "{}let {}: {} = if *{} {{ 1 }} else {{ 0 }};",
                            cg::ind(ind + 2),
                            name,
                            typ,
                            name
                        )?;
                        writeln!(
                            out,
                            "{}offset += {}.serialize(&mut wire_buf[offset..]);",
                            cg::ind(ind + 2),
                            name
                        )?;
                    }
                    Field::Field { name, .. } => {
                        writeln!(
                            out,
                            "{}offset += {}.serialize(&mut wire_buf[offset..]);",
                            cg::ind(ind + 2),
                            name
                        )?;
                    }
                    Field::List { name, rs_typ, .. } if rs_typ == "char" => {
                        writeln!(
                            out,
                            "{}(&mut wire_buf[offset..]).copy_from_slice({}.as_bytes());",
                            cg::ind(ind + 2),
                            name
                        )?;
                        writeln!(out, "{}offset += {}.len();", cg::ind(ind + 2), name)?;
                    }
                    Field::List { name, .. } => {
                        writeln!(out, "{}for el in {} {{", cg::ind(ind + 2), name)?;
                        writeln!(
                            out,
                            "{}offset += el.serialize(&mut wire_buf[offset..]);",
                            cg::ind(ind + 3)
                        )?;
                        writeln!(out, "{}}}", cg::ind(ind + 2))?;
                    }
                    Field::Switch { name, is_mask, .. } => {
                        let acc = if *is_mask { ".as_slice()" } else { "" };
                        writeln!(
                            out,
                            "{}offset += {}{}.serialize(&mut wire_buf[offset..]);",
                            cg::ind(ind + 2),
                            name,
                            acc
                        )?;
                    }
                    Field::Pad {
                        wire_sz: Expr::Value(sz),
                        ..
                    } => {
                        writeln!(out, "{}offset += {};", cg::ind(ind + 2), sz)?;
                    }
                    Field::AlignPad {
                        wire_sz: Expr::AlignPad(sz, _),
                        ..
                    } => {
                        writeln!(
                            out,
                            "{}offset += base::align_pad(offset, {});",
                            cg::ind(ind + 2),
                            sz
                        )?;
                    }
                    _ => unreachable!("{:#?}", f),
                }
            }
            writeln!(out, "{}}}", cg::ind(ind + 1))?;
        }

        writeln!(out, "{}}}", cg::ind(ind))?;
        if is_mask {
            writeln!(out, "{}}}", cg::ind(2))?;
        }
        writeln!(out, "{}offset", cg::ind(2))?;
        writeln!(out, "    }}")?;
        Ok(())
    }

    fn emit_mask_switch_impl<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        mask: &(Option<String>, String),
        cases: &[SwitchCase],
    ) -> io::Result<()> {
        let mask = (&mask.0, &mask.1).qualified_rs_typ();
        writeln!(out)?;
        writeln!(out, "impl {} {{", rs_typ)?;
        writeln!(
            out,
            "    pub(crate) fn get_mask(slice: &[{}]) -> {} {{",
            rs_typ, mask
        )?;
        writeln!(out, "        let mut res = {}::empty();", mask)?;
        writeln!(out, "        for el in slice {{")?;
        writeln!(out, "            match el {{")?;
        for c in cases {
            let indent = "                ";
            writeln!(out, "{}{}::{}{{..}} => {{", indent, rs_typ, c.name)?;
            for expr in &c.exprs {
                if let Expr::MaskRef { item, .. } = expr {
                    writeln!(out, "{}    res |= {}::{};", indent, mask, item)?;
                } else {
                    unreachable!();
                }
            }
            writeln!(out, "{}}}", indent)?;
        }
        writeln!(out, "            }}")?;
        writeln!(out, "        }}")?;
        writeln!(out, "        res")?;
        writeln!(out, "    }}")?;
        writeln!(out)?;
        writeln!(
            out,
            "    pub(crate) fn is_sorted_distinct(slice: &[{}]) -> bool {{",
            rs_typ
        )?;
        writeln!(out, "        if slice.len() <= 1 {{")?;
        writeln!(out, "            true")?;
        writeln!(out, "        }} else {{")?;
        writeln!(out, "            let mut last = slice[0].get_ord();")?;
        writeln!(
            out,
            "            slice[1..].iter().map(|el| el.get_ord()).all(|o| {{"
        )?;
        writeln!(out, "                let lasto = last;")?;
        writeln!(out, "                last = o;")?;
        writeln!(out, "                lasto < o")?;
        writeln!(out, "            }})")?;
        writeln!(out, "        }}")?;
        writeln!(out, "    }}")?;
        writeln!(out)?;
        writeln!(out, "    fn get_ord(&self) -> u32 {{")?;
        writeln!(out, "        match self {{")?;
        for (i, c) in cases.iter().enumerate() {
            writeln!(out, "            {}::{}{{..}} => {},", rs_typ, c.name, i)?;
        }
        writeln!(out, "        }}")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;
        Ok(())
    }

    fn emit_enum_switch_impl<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        r#enum: &(Option<String>, String),
        cases: &[SwitchCase],
    ) -> io::Result<()> {
        let r#enum = (&r#enum.0, &r#enum.1).qualified_rs_typ();
        writeln!(out)?;
        writeln!(out, "impl {} {{", rs_typ)?;
        writeln!(out, "    pub(crate) fn get_enum(&self) -> {} {{", r#enum)?;
        writeln!(out, "        match self {{")?;
        for c in cases {
            let indent = "        ";
            writeln!(out, "{}{}::{}{{..}} => {{", indent, rs_typ, c.name)?;
            for expr in &c.exprs {
                if let Expr::EnumRef { item, .. } = expr {
                    writeln!(out, "{}    {}::{}", indent, r#enum, item)?;
                } else {
                    unreachable!();
                }
            }
            writeln!(out, "{}}}", indent)?;
        }
        writeln!(out, "        }}")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;
        Ok(())
    }
}

use crate::{cg, cg::util, ir};

use super::{
    AsModRsTyp, CodeGen, Expr, Field, QualifiedRsTyp, RsTyp, TypeInfo, UnionTypeField,
    UnionVariant, UnionVariantContent, WireSz,
};

use std::io::{self, Write};

impl CodeGen {
    pub(super) fn resolve_union(
        &mut self,
        typ: &str,
        fields: &[ir::Field],
        _doc: &Option<ir::Doc>,
    ) {
        let rs_typ = cg::rust_type_name(typ);

        let has_type_field = fields
            .iter()
            .any(|f| matches!(f, ir::Field::Field{name, ..} if name == "type"));

        let (variants, wire_sz, type_field) = if has_type_field {
            self.resolve_type_field_union_variants(&rs_typ, fields)
        } else {
            self.resolve_union_variants(&rs_typ, fields)
        };

        let typ_info = TypeInfo::Union {
            module: None,
            rs_typ,
            variants,
            wire_sz,
            type_field,
        };
        self.register_typ(typ.to_string(), typ_info);
    }

    fn resolve_union_variants(
        &mut self,
        _union_rs_typ: &str,
        fields: &[ir::Field],
    ) -> (Vec<UnionVariant>, Expr, Option<UnionTypeField>) {
        let mut vec = Vec::new();
        let mut wire_sz = Expr::Value(0usize);

        for f in fields {
            match f {
                ir::Field::Field { name, typ, .. } => {
                    let (module, typ) = util::extract_module(typ);
                    let typinfo = self.find_typinfo(module, typ);
                    let rs_typ = typinfo.rs_typ();
                    let f_wire_sz = typinfo.wire_sz();

                    let content = UnionVariantContent::RsTyp(rs_typ.to_string());

                    if let (Expr::Value(wire_sz), Expr::Value(f_wire_sz)) =
                        (&mut wire_sz, &f_wire_sz)
                    {
                        *wire_sz = (*wire_sz).max(*f_wire_sz);
                    }

                    let variant = util::tit_cap(name);

                    vec.push(UnionVariant {
                        variant,
                        module: module.map(str::to_owned),
                        content,
                    });
                }
                ir::Field::List {
                    name,
                    typ,
                    len_expr: ir::Expr::Value(sz),
                } => {
                    let variant = util::tit_cap(name);
                    let (module, typ) = util::extract_module(typ);
                    let typinfo = self.find_typinfo(module, typ);
                    let rs_typ = typinfo.rs_typ();
                    let f_wire_sz = typinfo.wire_sz();
                    let f_wire_sz = Expr::Op(
                        "*".to_string(),
                        Box::new(Expr::Value(*sz)),
                        Box::new(f_wire_sz),
                    );
                    let f_wire_sz = f_wire_sz.reduce();

                    if let (Expr::Value(wire_sz), Expr::Value(f_wire_sz)) =
                        (&mut wire_sz, &f_wire_sz)
                    {
                        *wire_sz = (*wire_sz).max(*f_wire_sz);
                    }

                    vec.push(UnionVariant {
                        variant,
                        module: module.map(str::to_owned),
                        content: UnionVariantContent::Array(rs_typ.to_string(), *sz),
                    });
                }
                ir::Field::Pad(..) => unreachable!("pad in union??"),
                _ => unreachable!("{:#?}"),
            }
        }
        (vec, wire_sz, None)
    }

    fn resolve_type_field_union_variants(
        &mut self,
        union_rs_typ: &str,
        fields: &[ir::Field],
    ) -> (Vec<UnionVariant>, Expr, Option<UnionTypeField>) {
        let mut vec = Vec::new();
        let mut wire_sz = Expr::Value(0usize);
        let mut type_field = None;

        for f in fields {
            match f {
                ir::Field::Field {
                    name, typ, r#enum, ..
                } => {
                    if name == "type" {
                        assert_eq!(typ.as_str(), "CARD8");
                        let (enu_module, enu_typ) = r#enum
                            .as_ref()
                            .map(|typ| {
                                let (module, typ) = util::extract_module(typ);
                                (module.map(str::to_owned), typ.to_string())
                            })
                            .unwrap_or_else(|| (None, union_rs_typ.to_string() + "Type"));
                        type_field = Some(UnionTypeField {
                            offset: 0,
                            enu_module,
                            enu_typ,
                        });
                        continue;
                    }

                    let (module, typ) = util::extract_module(typ);
                    if name == "common" {
                        if module.is_none() {
                            self.typ_need_add(typ, -1);
                        }
                        continue;
                    }
                    let typinfo = self.find_typinfo(module, typ);
                    let rs_typ = typinfo.rs_typ();
                    let f_wire_sz = typinfo.wire_sz();

                    let final_typinfo = self.find_typinfo_recurse(module, typ);

                    let content = match final_typinfo {
                        TypeInfo::Struct { fields, .. } => {
                            UnionVariantContent::Struct(fields.clone())
                        }
                        _ => UnionVariantContent::RsTyp(rs_typ.to_string()),
                    };

                    if let (Expr::Value(wire_sz), Expr::Value(f_wire_sz)) =
                        (&mut wire_sz, &f_wire_sz)
                    {
                        *wire_sz = (*wire_sz).max(*f_wire_sz);
                    }

                    let variant = util::tit_cap(name);

                    vec.push(UnionVariant {
                        variant,
                        module: module.map(str::to_owned),
                        content,
                    });

                    if module.is_none() {
                        self.typ_need_add(typ, -1);
                    }
                }
                ir::Field::Pad(..) => unreachable!("pad in union??"),
                _ => unreachable!(),
            }
        }
        (vec, wire_sz, type_field)
    }

    pub(super) fn emit_union<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        variants: &[UnionVariant],
        wire_sz: &Expr,
        type_field: &Option<UnionTypeField>,
    ) -> io::Result<()> {
        writeln!(out)?;
        writeln!(out, "#[derive(Clone, Debug)]")?;
        writeln!(out, "pub enum {} {{", rs_typ)?;
        for v in variants {
            match &v.content {
                UnionVariantContent::RsTyp(rs_typ) => {
                    writeln!(out, "    {}({}),", v.variant, rs_typ)?;
                }
                UnionVariantContent::Array(rs_typ, sz) => {
                    writeln!(out, "    {}([{}; {}]),", v.variant, rs_typ, sz)?;
                }
                UnionVariantContent::Struct(fields) => {
                    if fields.is_empty() {
                        writeln!(out, "    {},", v.variant)?;
                    } else {
                        writeln!(out, "    {}{{", v.variant)?;
                        for f in fields {
                            if is_type_field(f) {
                                continue;
                            }
                            match f {
                                Field::Field {
                                    name,
                                    module,
                                    rs_typ,
                                    ..
                                } => {
                                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                                    writeln!(out, "        {}: {},", name, q_rs_typ)?;
                                }
                                Field::List {
                                    name,
                                    module,
                                    rs_typ,
                                    len_expr: Expr::Value(sz),
                                    ..
                                } => {
                                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                                    writeln!(out, "        {}: [{}; {}],", name, q_rs_typ, sz)?;
                                }
                                _ => {}
                            }
                        }
                        writeln!(out, "    }},")?;
                    }
                }
            }
        }
        writeln!(out, "}}")?;

        if let Some(type_field) = type_field {
            self.emit_union_ctor_type_field(out, rs_typ, variants, type_field)?;
        }

        let wire_sz = match wire_sz {
            Expr::Value(wire_sz) => wire_sz,
            _ => unreachable!("{:#?}", wire_sz),
        };

        writeln!(out)?;
        writeln!(out, "impl base::Wired for {} {{", rs_typ)?;
        writeln!(out, "    type Params = ();")?;
        writeln!(out)?;
        writeln!(
            out,
            "    unsafe fn compute_wire_len(_ptr: *const u8, _params: Self::Params) -> usize {{ {} }}", wire_sz
        )?;
        writeln!(out)?;
        writeln!(out, "    fn wire_len(&self) -> usize {{ {} }}", wire_sz)?;
        writeln!(out)?;
        writeln!(
            out,
            "    fn serialize(&self, wire_buf: &mut [u8]) -> usize {{"
        )?;
        writeln!(out, "        match self {{")?;
        for uv in variants {
            match &uv.content {
                UnionVariantContent::RsTyp(_rs_typ) => {
                    assert!(type_field.is_none());
                    let name = cg::rust_field_name(&uv.variant);
                    writeln!(
                        out,
                        "{}{}::{}({}) => {{",
                        cg::ind(3),
                        rs_typ,
                        uv.variant,
                        name
                    )?;
                    writeln!(out, "{}{}.serialize(wire_buf);", cg::ind(4), name)?;
                    writeln!(out, "{}}}", cg::ind(3))?;
                }
                UnionVariantContent::Array(_rs_typ, _sz) => {
                    assert!(type_field.is_none());
                    let name = cg::rust_field_name(&uv.variant);
                    writeln!(
                        out,
                        "{}{}::{}({}) => {{",
                        cg::ind(3),
                        rs_typ,
                        uv.variant,
                        name
                    )?;
                    writeln!(
                        out,
                        "{}let me = unsafe {{ std::slice::from_raw_parts(",
                        cg::ind(4)
                    )?;
                    writeln!(
                        out,
                        "{}{}.as_ptr() as *const u8, {}",
                        cg::ind(5),
                        name,
                        wire_sz
                    )?;
                    writeln!(out, "{})}};", cg::ind(4))?;
                    writeln!(
                        out,
                        "{}let wire_buf = &mut wire_buf[..{}];",
                        cg::ind(4),
                        wire_sz
                    )?;
                    writeln!(out, "{}wire_buf.copy_from_slice(me);", cg::ind(4))?;
                    writeln!(out, "{}}}", cg::ind(3))?;
                }
                UnionVariantContent::Struct(fields) => {
                    writeln!(out, "{}{}::{}{{", cg::ind(3), rs_typ, uv.variant)?;
                    for f in fields {
                        if is_type_field(f) {
                            continue;
                        }
                        match f {
                            Field::Field { name, .. } | Field::List { name, .. } => {
                                writeln!(out, "{}{},", cg::ind(4), name)?;
                            }
                            _ => {}
                        }
                    }
                    writeln!(out, "{}}} => {{", cg::ind(3))?;
                    for f in fields.iter() {
                        if is_type_field(f) {
                            let type_field = type_field.as_ref().unwrap();
                            let enum_typ = self.find_typinfo(
                                type_field.enu_module.as_deref(),
                                &type_field.enu_typ,
                            );
                            let enum_expr = enum_typ.qualified_rs_typ() + "::" + &uv.variant;
                            writeln!(
                                out,
                                "{}wire_buf[0] += unsafe {{ std::mem::transmute::<_, u32>({}) }} as u8;",
                                cg::ind(4),
                                enum_expr,
                            )?;
                            continue;
                        }
                        match f {
                            Field::Field {
                                name,
                                wire_off: Expr::Value(off),
                                ..
                            } => {
                                writeln!(
                                    out,
                                    "{}{}.serialize(&mut wire_buf[{}..]);",
                                    cg::ind(4),
                                    name,
                                    off
                                )?;
                            }
                            Field::List {
                                name,
                                wire_off: Expr::Value(off),
                                wire_sz: Expr::Value(sz),
                                ..
                            } => {
                                writeln!(
                                    out,
                                    "{}(&mut wire_buf[{}..{}]).copy_from_slice({});",
                                    cg::ind(4),
                                    off,
                                    *off + *sz,
                                    name,
                                )?;
                            }
                            Field::Pad { .. } => {}
                            _ => unreachable!(),
                        }
                    }
                    writeln!(out, "{}}}", cg::ind(3))?;
                }
            }
        }
        writeln!(out, "        }}")?;
        writeln!(out, "        {}", wire_sz)?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        Ok(())
    }

    fn emit_union_ctor_type_field<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        variants: &[UnionVariant],
        type_field: &UnionTypeField,
    ) -> io::Result<()> {
        let UnionTypeField {
            enu_module,
            enu_typ,
            offset,
        } = type_field;

        let (items, _) = {
            let mod_rs_typ = (enu_module, enu_typ);
            let mod_rs_typ = mod_rs_typ.as_mod_rs_typ();
            let typ_info = self.find_typinfo_recurse(mod_rs_typ.0, mod_rs_typ.1);

            if let TypeInfo::Enum { items, .. } = typ_info {
                (
                    //map_type_field_enum_items(&self.xcb_mod, rs_typ, items),
                    items,
                    typ_info.qualified_rs_typ(),
                )
            } else {
                unreachable!()
            }
        };

        writeln!(out)?;
        writeln!(out, "impl {} {{", rs_typ)?;
        writeln!(
            out,
            "    unsafe fn from_data(wire_data: &[u8]) -> {} {{",
            rs_typ
        )?;
        writeln!(out, "        let r#type = wire_data[{}] as u32;", offset)?;
        writeln!(out, "        match r#type {{")?;
        for item in items {
            let variant = variants.iter().find(|v| v.variant == item.0).unwrap();
            match &variant.content {
                UnionVariantContent::RsTyp(..) => unreachable!(),
                UnionVariantContent::Array(..) => unreachable!(),
                UnionVariantContent::Struct(fields) => {
                    if fields.is_empty() {
                        writeln!(
                            out,
                            "            {} => {}::{},",
                            item.1, rs_typ, variant.variant
                        )?;
                    } else {
                        writeln!(
                            out,
                            "            {} => {}::{}{{",
                            item.1, rs_typ, variant.variant
                        )?;

                        for f in fields {
                            if is_type_field(f) {
                                continue;
                            }
                            match f {
                                Field::Field {
                                    name,
                                    wire_off: Expr::Value(off),
                                    module,
                                    rs_typ,
                                    ..
                                } => {
                                    let q_rs_typ = (module, rs_typ).qualified_rs_typ();
                                    writeln!(
                                        out,
                                        "                {}: *(wire_data.as_ptr().add({}) as *const {}),",
                                        name,
                                        off,
                                        q_rs_typ,
                                    )?;
                                }
                                Field::List {
                                    name,
                                    wire_off: Expr::Value(off),
                                    wire_sz: Expr::Value(sz),
                                    rs_typ,
                                    ..
                                } if rs_typ == "u8" => {
                                    writeln!(
                                        out,
                                        "{}{}: wire_data[{}..{}].try_into().unwrap(),",
                                        cg::ind(4),
                                        name,
                                        *off,
                                        *off + *sz
                                    )?;
                                }
                                Field::Pad { .. } => {}
                                _ => unreachable!(),
                            }
                        }
                        writeln!(out, "            }},")?;
                    }
                }
            }
        }
        writeln!(
            out,
            "            _ => unreachable!(\"unexpected type value for {}::{}\"),",
            self.xcb_mod, rs_typ
        )?;
        writeln!(out, "        }}")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        Ok(())
    }
}

fn is_type_field(f: &Field) -> bool {
    match f {
        Field::Field { name, .. } => name == "r#type",
        _ => false,
    }
}

use super::{CodeGen, QualifiedRsTyp, RsTyp, TypeInfo, UnionVariantContent};
use crate::cg;

use std::io::{self, Write};

use super::{util, UnionVariant};

impl CodeGen {
    pub(super) fn resolve_xid(&mut self, typ: &str) {
        let rs_typ = match (self.xcb_mod.as_str(), typ) {
            ("present", "EVENT") => "EventXid".to_string(),
            (_, typ) => cg::rust_type_name(typ),
        };
        let info = TypeInfo::Xid {
            module: None,
            rs_typ,
        };
        self.register_typ(typ.to_string(), info);
    }

    pub(super) fn resolve_xidunion(&mut self, typ: &str, xidtypes: &[String]) {
        let rs_typ = cg::rust_type_name(typ);
        let variants: Vec<_> = xidtypes
            .iter()
            .map(|typ| {
                let (module, typ) = self.extract_module(typ);
                let rs_typ = self.find_typinfo(module, typ).rs_typ().to_string();

                let variant = match module {
                    Some(module) => util::tit_cap(module) + &rs_typ,
                    None => rs_typ.clone(),
                };
                UnionVariant {
                    variant,
                    module: module.map(str::to_owned),
                    content: UnionVariantContent::RsTyp(rs_typ),
                }
            })
            .collect();

        let info = TypeInfo::XidUnion {
            module: None,
            rs_typ,
            variants,
        };
        self.register_typ(typ.to_string(), info);
    }

    pub(super) fn emit_xid<O: Write>(&self, out: &mut O, rs_typ: &str) -> io::Result<()> {
        writeln!(out)?;
        writeln!(out, "#[derive(Copy, Clone, Debug, PartialEq, Eq)]")?;
        writeln!(out, "#[repr(C)]")?;
        writeln!(out, "pub struct {} {{", rs_typ)?;
        writeln!(out, "    res_id: u32,")?;
        writeln!(out, "}}")?;
        writeln!(out)?;
        writeln!(out, "impl base::Xid for {} {{", rs_typ)?;
        writeln!(
            out,
            "    fn none() -> Self {{ {} {{ res_id: 0 }} }}",
            rs_typ
        )?;
        writeln!(out, "    fn resource_id(&self) -> u32 {{ self.res_id }}")?;
        writeln!(out, "}}")?;
        writeln!(out)?;
        writeln!(out, "impl base::XidNew for {} {{", rs_typ)?;
        writeln!(
            out,
            "    unsafe fn new(res_id: u32) -> Self {{ {} {{ res_id }} }}",
            rs_typ
        )?;
        writeln!(out, "}}")?;

        self.emit_sizeof_test(out, rs_typ, 4)?;

        Ok(())
    }

    pub(super) fn emit_xidunion<O: Write>(
        &self,
        out: &mut O,
        rs_typ: &str,
        variants: &[UnionVariant],
    ) -> io::Result<()> {
        let has_unknown = matches!(
            (self.xcb_mod.as_str(), rs_typ),
            ("xproto", "Drawable") | ("glx", "Drawable")
        );

        writeln!(out)?;
        writeln!(out, "#[derive(Copy, Clone, Debug)]")?;
        writeln!(out, "pub enum {} {{", rs_typ)?;
        writeln!(out, "    None,")?;
        if has_unknown {
            writeln!(out, "    /// Whether the drawable is a `Window` or a `Pixmap` is only known to the user context")?;
            writeln!(out, "    Unknown(u32),")?;
        }
        for v in variants {
            if let UnionVariantContent::RsTyp(rs_typ) = &v.content {
                let mod_rs_typ = (&v.module, rs_typ);
                writeln!(out, "    {}({}),", v.variant, mod_rs_typ.qualified_rs_typ())?;
            } else {
                unreachable!();
            }
        }
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "impl base::Xid for {} {{", rs_typ)?;
        writeln!(out, "    fn none() -> Self {{ {}::None }}", rs_typ)?;
        writeln!(out)?;
        writeln!(out, "    fn resource_id(&self) -> u32 {{")?;
        writeln!(out, "        match self {{")?;
        writeln!(out, "            {}::None => 0,", rs_typ)?;
        if has_unknown {
            writeln!(out, "{}Drawable::Unknown(id) => *id,", cg::ind(3))?;
        }
        for v in variants {
            writeln!(
                out,
                "            {}::{}(xid) => xid.resource_id(),",
                rs_typ, v.variant
            )?;
        }
        writeln!(out, "        }}")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;

        writeln!(out)?;
        writeln!(out, "impl PartialEq for {} {{", rs_typ)?;
        writeln!(out, "    fn eq(&self, rhs: &{}) -> bool {{", rs_typ)?;
        writeln!(out, "        self.resource_id() == rhs.resource_id()")?;
        writeln!(out, "    }}")?;
        writeln!(out, "}}")?;
        writeln!(out)?;
        writeln!(out, "impl Eq for {} {{}}", rs_typ)?;

        for v in variants {
            let variant = if v.variant == "XprotoWindow" {
                "xproto::Window"
            } else {
                &v.variant
            };

            writeln!(out)?;
            writeln!(out, "impl PartialEq<{}> for {} {{", variant, rs_typ)?;
            writeln!(out, "    fn eq(&self, rhs: &{}) -> bool {{", variant)?;
            writeln!(out, "        self.resource_id() == rhs.resource_id()")?;
            writeln!(out, "    }}")?;
            writeln!(out, "}}")?;
            writeln!(out)?;
            writeln!(out, "impl PartialEq<{}> for {} {{", rs_typ, variant)?;
            writeln!(out, "    fn eq(&self, rhs: &{}) -> bool {{", rs_typ)?;
            writeln!(out, "        self.resource_id() == rhs.resource_id()")?;
            writeln!(out, "    }}")?;
            writeln!(out, "}}")?;
        }
        Ok(())
    }
}

