extern crate libc;
extern crate xcb;

use xcb::ffi::xkb::*;
use xcb::ffi::*;

use libc::{c_char, c_int, c_void};
use std::ptr::{null, null_mut};

fn main() {
    unsafe {
        let mut screen_num: c_int = 0;
        let c = xcb_connect(null(), &mut screen_num);
        if c.is_null() {
            panic!();
        }

        // generally useful to retrieve the first event from this
        // extension. event response_type will be set on this
        let _first_ev = {
            xcb_prefetch_extension_data(c, &mut xcb_xkb_id);

            let reply = xcb_get_extension_data(c, &mut xcb_xkb_id);
            if reply.is_null() || (*reply).present == 0 {
                panic!("XKB extension not supported by X server");
            }

            (*reply).first_event
        };

        // we need at least xcb-xkb-1.0 to be available on client
        // machine
        {
            let cookie = xcb_xkb_use_extension(c, 1, 0);
            let reply = xcb_xkb_use_extension_reply(c, cookie, null_mut());
            if reply.is_null() {
                panic!("could not get xkb extension supported version");
            }
            if (*reply).supported == 0 {
                libc::free(reply as *mut c_void);
                panic!("xkb-1.0 is not supported");
            }
            libc::free(reply as *mut c_void);
        }

        // we now select what events we want to receive
        // such as map change, keyboard hotplug ...
        // note that key strokes are given directly by
        // the XCB_KEY_PRESS event from xproto, not by xkb
        {
            let map_parts = XCB_XKB_MAP_PART_KEY_TYPES
                | XCB_XKB_MAP_PART_KEY_SYMS
                | XCB_XKB_MAP_PART_MODIFIER_MAP
                | XCB_XKB_MAP_PART_EXPLICIT_COMPONENTS
                | XCB_XKB_MAP_PART_KEY_ACTIONS
                | XCB_XKB_MAP_PART_KEY_BEHAVIORS
                | XCB_XKB_MAP_PART_VIRTUAL_MODS
                | XCB_XKB_MAP_PART_VIRTUAL_MOD_MAP;

            let events = XCB_XKB_EVENT_TYPE_NEW_KEYBOARD_NOTIFY
                | XCB_XKB_EVENT_TYPE_MAP_NOTIFY
                | XCB_XKB_EVENT_TYPE_STATE_NOTIFY;

            let cookie = xcb_xkb_select_events_checked(
                c,
                XCB_XKB_ID_USE_CORE_KBD as u16,
                events as u16,
                0,
                events as u16,
                map_parts as u16,
                map_parts as u16,
                null(),
            );
            let err = xcb_request_check(c, cookie);
            if !err.is_null() {
                panic!("failed to select notify events from xcb xkb");
            }
        }

        // proceed with create_window and event loop...
    }
}

// returns the glx version in a decimal form
// eg. 1.3  => 13
fn glx_dec_version(dpy: *mut xlib::Display) -> i32 {
    let mut maj: c_int = 0;
    let mut min: c_int = 0;
    unsafe {
        if glXQueryVersion(dpy, &mut maj as *mut c_int, &mut min as *mut c_int) == 0 {
            panic!("cannot get glx version");
        }
    }
    (maj * 10 + min) as i32
}

fn main() {
    unsafe {
        let (conn, screen_num) = xcb::Connection::connect_with_xlib_display().unwrap();
        conn.set_event_queue_owner(xcb::EventQueueOwner::Xcb);

        if glx_dec_version(conn.get_raw_dpy()) < 13 {
            panic!("glx-1.3 is not supported");
        }

        let fbc = get_glxfbconfig(
            conn.get_raw_dpy(),
            screen_num,
            &[
                GLX_X_RENDERABLE,
                1,
                GLX_DRAWABLE_TYPE,
                GLX_WINDOW_BIT,
                GLX_RENDER_TYPE,
                GLX_RGBA_BIT,
                GLX_X_VISUAL_TYPE,
                GLX_TRUE_COLOR,
                GLX_RED_SIZE,
                8,
                GLX_GREEN_SIZE,
                8,
                GLX_BLUE_SIZE,
                8,
                GLX_ALPHA_SIZE,
                8,
                GLX_DEPTH_SIZE,
                24,
                GLX_STENCIL_SIZE,
                8,
                GLX_DOUBLEBUFFER,
                1,
                0,
            ],
        let vi: *const xlib::XVisualInfo = glXGetVisualFromFBConfig(conn.get_raw_dpy(), fbc);

        let dri2_ev = {
            conn.prefetch_extension_data(dri2::id());
            match conn.get_extension_data(dri2::id()) {
                None => {
                    panic!("could not load dri2 extension")
                }
                Some(r) => r.first_event(),
            }
        };

        let (wm_protocols, wm_delete_window) = {
            let pc = xcb::intern_atom(&conn, false, "WM_PROTOCOLS");
            let dwc = xcb::intern_atom(&conn, false, "WM_DELETE_WINDOW");

            let p = match pc.get_reply() {
                Ok(p) => p.atom(),
                Err(_) => panic!("could not load WM_PROTOCOLS atom"),
            };
            let dw = match dwc.get_reply() {
                Ok(dw) => dw.atom(),
                Err(_) => panic!("could not load WM_DELETE_WINDOW atom"),
            };
            (p, dw)
        };

        let setup = conn.get_setup();
        let screen = setup.roots().nth((*vi).screen as usize).unwrap();

        let cmap = conn.generate_id();
        let win = conn.generate_id();

        xcb::create_colormap(
            &conn,
            xcb::COLORMAP_ALLOC_NONE as u8,
            cmap,
            screen.root(),
            (*vi).visualid as u32,
        );
        let cw_values = [
            (xcb::CW_BACK_PIXEL, screen.white_pixel()),
            (xcb::CW_BORDER_PIXEL, screen.black_pixel()),
            (
                xcb::CW_EVENT_MASK,
                xcb::EVENT_MASK_KEY_PRESS | xcb::EVENT_MASK_EXPOSURE,
            ),
            (xcb::CW_COLORMAP, cmap),
        ];

