        ctx_error_occurred = false;
        let old_handler = xlib::XSetErrorHandler(Some(ctx_error_handler));

        let context_attribs: [c_int; 5] = [
            GLX_CONTEXT_MAJOR_VERSION_ARB as c_int,
            3,
            GLX_CONTEXT_MINOR_VERSION_ARB as c_int,
            0,
            0,
