pub(crate) unsafe fn resolve_event(
    event: *mut xcb_generic_event_t,
    extension_data: &[EventExtensionData],
) -> Event {
    let response_type = (*event).response_type & 0x7F;

    if response_type == XCB_GE_GENERIC {
        let event = event as *mut xcb_ge_generic_event_t;
        let extension = (*event).extension;
        for ext in extension_data {
            if ext.major_opcode == extension {
                match ext.ext {
                    #[cfg(feature = "present")]
                    Extension::Present => {
                        return Event::Present(present::Event::resolve_wire_ge_event(event));
                    }
                    #[cfg(feature = "xinput")]
                    Extension::Input => {
                        return Event::Input(xinput::Event::resolve_wire_ge_event(event));
                    }
                    _ => panic!("could not resolve Generic Event extension"),
                }
            }
        }
    }

    for data in extension_data {
        if response_type >= data.first_event {
            match data.ext {
                #[cfg(feature = "damage")]
                Extension::Damage => {
                    return Event::Damage(damage::Event::resolve_wire_event(
                        data.first_event,
                        event,
                    ));
                }

                #[cfg(feature = "dri2")]
                Extension::Dri2 => {
                    return Event::Dri2(dri2::Event::resolve_wire_event(data.first_event, event));
                }

                #[cfg(feature = "glx")]
                Extension::Glx => {
                    return Event::Glx(glx::Event::resolve_wire_event(data.first_event, event));
                }

                #[cfg(feature = "present")]
                Extension::Present => {
                    return Event::Present(present::Event::resolve_wire_event(
                        data.first_event,
                        event,
                    ));
                }

                #[cfg(feature = "randr")]
                Extension::RandR => {
                    return Event::RandR(randr::Event::resolve_wire_event(data.first_event, event));
                }

                #[cfg(feature = "screensaver")]
                Extension::ScreenSaver => {
                    return Event::ScreenSaver(screensaver::Event::resolve_wire_event(
                        data.first_event,
                        event,
                    ));
                }

                #[cfg(feature = "shape")]
                Extension::Shape => {
                    return Event::Shape(shape::Event::resolve_wire_event(data.first_event, event));
                }

                #[cfg(feature = "shm")]
                Extension::Shm => {
                    return Event::Shm(shm::Event::resolve_wire_event(data.first_event, event));
                }

                #[cfg(feature = "sync")]
                Extension::Sync => {
                    return Event::Sync(sync::Event::resolve_wire_event(data.first_event, event));
                }

                #[cfg(feature = "xfixes")]
                Extension::XFixes => {
                    return Event::XFixes(xfixes::Event::resolve_wire_event(
                        data.first_event,
                        event,
                    ));
                }

                #[cfg(feature = "xinput")]
                Extension::Input => {
                    return Event::Input(xinput::Event::resolve_wire_event(
                        data.first_event,
                        event,
                    ));
                }

                #[cfg(feature = "xkb")]
                Extension::Xkb => {
                    return Event::Xkb(xkb::Event::resolve_wire_event(data.first_event, event));
                }

                #[cfg(feature = "xprint")]
                Extension::XPrint => {
                    return Event::XPrint(xprint::Event::resolve_wire_event(
                        data.first_event,
                        event,
                    ));
                }

                #[cfg(feature = "xv")]
                Extension::Xv => {
                    return Event::Xv(xv::Event::resolve_wire_event(data.first_event, event));
                }

                _ => {}
            }
        }
    }

    Event::X(x::Event::resolve_wire_event(0, event))
}

use crate::base::{self, Wired};
use crate::x::{Cw, Depth, DepthBuf, VisualClass, Visualtype};

fn visual_data(bits_per_rgb_value: u8) -> Vec<u8> {
    vec![
        0x50,
        0x40,
        0x30,
        0x20,               // visual_id
        3,                  // visual class
        bits_per_rgb_value, // bits_per_rgb_value
        0x50,
        0x40, // colormap_entries
        0xff,
        0x00,
        0x00,
        0x00, // red_mask
        0x00,
        0xff,
        0x00,
        0x00, // green_mask
        0x00,
        0x00,
        0xff,
        0x00, // blue_mask
        0x00,
        0x00,
        0x00,
        0x00, // pad
    ]
}

fn depth_data(visual_bprv: &[u8], extra_garbage: usize) -> Vec<u8> {
    let data: &[u8] = &[
        16,   // depth
        0x00, // pad
        0x02, 0x00, // visuals_len
        0x00, 0x00, 0x00, 0x00, // pad
    ];
    let mut vec = Vec::from(data);
    let visuals_data = visual_bprv.iter().map(|bprv| visual_data(*bprv));
    for mut vd in visuals_data {
        vec.append(&mut vd);
    }
    // append garbage
    for g in 0..extra_garbage {
        vec.push(((g ^ extra_garbage) & 0xff) as u8);
    }
    vec
}

#[test]
#[cfg(target_endian = "little")]
fn test_fixbuf_from_data() {
    let data = visual_data(24);

    let vt = unsafe { Visualtype::from_data(&data) };

    assert_eq!(vt.visual_id(), 0x20304050);
    assert_eq!(vt.class(), VisualClass::PseudoColor);
    assert_eq!(vt.bits_per_rgb_value(), 24);
    assert_eq!(vt.colormap_entries(), 0x4050);
    assert_eq!(vt.red_mask(), 0x000000ff);
    assert_eq!(vt.green_mask(), 0x0000ff00);
    assert_eq!(vt.blue_mask(), 0x00ff0000);
}

#[test]
#[cfg(target_endian = "little")]
fn test_dynbuf_from_data() {
    let mut data = depth_data(&[32, 24], 4);

    assert_eq!(data.len(), 60);
    assert_eq!(unsafe { Depth::compute_wire_len(data.as_ptr(), ()) }, 56);
    {
        let depth = unsafe { Depth::from_data(&data[0..56]) };
        assert_eq!(depth.depth(), 16);
        let visuals = depth.visuals();
        assert_eq!(visuals.len(), 2);
        let vt = visuals[0];
        assert_eq!(vt.visual_id(), 0x20304050);
        assert_eq!(vt.class(), VisualClass::PseudoColor);
        assert_eq!(vt.bits_per_rgb_value(), 32);
        assert_eq!(vt.colormap_entries(), 0x4050);
        assert_eq!(vt.red_mask(), 0x000000ff);
        assert_eq!(vt.green_mask(), 0x0000ff00);
        assert_eq!(vt.blue_mask(), 0x00ff0000);
        let vt = visuals[1];
        assert_eq!(vt.visual_id(), 0x20304050);
        assert_eq!(vt.class(), VisualClass::PseudoColor);
        assert_eq!(vt.bits_per_rgb_value(), 24);
        assert_eq!(vt.colormap_entries(), 0x4050);
        assert_eq!(vt.red_mask(), 0x000000ff);
        assert_eq!(vt.green_mask(), 0x0000ff00);
        assert_eq!(vt.blue_mask(), 0x00ff0000);
    }

    // pop garbage
    data.pop();
    data.pop();
    data.pop();
    data.pop();

    let depth = unsafe { DepthBuf::from_data(data) };
    assert_eq!(depth.depth(), 16);
    let visuals = depth.visuals();
    assert_eq!(visuals.len(), 2);
    let vt = visuals[0];
    assert_eq!(vt.visual_id(), 0x20304050);
    assert_eq!(vt.class(), VisualClass::PseudoColor);
    assert_eq!(vt.bits_per_rgb_value(), 32);
    assert_eq!(vt.colormap_entries(), 0x4050);
    assert_eq!(vt.red_mask(), 0x000000ff);
    assert_eq!(vt.green_mask(), 0x0000ff00);
    assert_eq!(vt.blue_mask(), 0x00ff0000);
    let vt = visuals[1];
    assert_eq!(vt.visual_id(), 0x20304050);
    assert_eq!(vt.class(), VisualClass::PseudoColor);
    assert_eq!(vt.bits_per_rgb_value(), 24);
    assert_eq!(vt.colormap_entries(), 0x4050);
    assert_eq!(vt.red_mask(), 0x000000ff);
    assert_eq!(vt.green_mask(), 0x0000ff00);
    assert_eq!(vt.blue_mask(), 0x00ff0000);
}

