#[test]
fn test_cw_is_sorted_distinct() {
    assert!(Cw::is_sorted_distinct(&[
        Cw::BackPixel(4),
        Cw::BitGravity(4),
        Cw::WinGravity(4),
    ]));

    assert!(!Cw::is_sorted_distinct(&[
        Cw::BackPixel(4),
        Cw::WinGravity(4),
        Cw::BitGravity(4),
    ]));

    assert!(!Cw::is_sorted_distinct(&[
        Cw::BackPixel(4),
        Cw::BitGravity(4),
        Cw::BitGravity(4),
    ]));

    assert!(!Cw::is_sorted_distinct(&[
        Cw::BackPixel(4),
        Cw::BitGravity(4),
        Cw::BitGravity(5),
    ]));
}

